rows["101:80744300"]="만약 당신이 그들을 죽이면, 나는 그들의 시체를 다시 살려줄 것이고, 그리고 네가 죽을 때, 나도 당신에게 똑같이 할 것이다."
rows["101:80796596"]="저는 우리의 군대에 착륙할 곳을 선택했습니다. 동쪽의 작은 반도,"
