rows["101:830539351"]="여기 이렇게 큰 곤경에 처할 줄 상상도 못했어요$B$B어쩌면 우리는 성전에서 떠나지 않아야했을지도 몰라"
rows["101:833218185"]="불꽃놀이 끝나면 여기 있어 잔을 찾아서 내린 친구들에게 드라마를 드라"
rows["101:833662340"]="저는 서둘러 발라리엘에게 돌아가겠어요. 여기서부터는 저 혼자서도 충분하니 해치울 수 있는 녀석들은 마저 해치워 주세요."
rows["101:835048281"]="리라가 널 지켜줄게 오브시디아가 여기 있다면 네가 끝내기 전까지는 내가 그녀를 바쁘게 할 거야"
rows["101:854056814"]="우리는 유르크 쿨티스트들이 터널 반대편에 모여 있다는 것을 알고 있습니다. 우리는 여기서 우리의 입장을 나타낼 것입니다."
rows["101:854936819"]="망할 거야, 우린 뒤로 물러나야 했지만 테르말플러그는 길을 잃었고 그는 그걸 알고 있어 "
