rows["101:907895294"]="그런 연쇄에 매달리는 건 추천하지 않지만 솔직히 말해서 내 머리카락에 좋은 영향을 줬어요"
rows["101:915090665"]="지금 내가 구속될 수도 있지만, 내 주인은 이 도시에 복수할 때 나를 해방시킬 것이다."
rows["101:928255120"]="폭탄과 로켓의 총알 냄새가 나네요"
rows["101:929519902"]="미안해 크로머시, 하지만 난 당신을 안심합니다."
rows["101:9325919"]="스톰하트 왕이 날 데려와서 손을 내밀게 했지"
rows["101:942388736"]="우리 사람들처럼, 호드도 항상 움직이고 있고, 끊임없이 변화하고 있습니다. 하지만 실수하지 마세요. 우리는 견딜 것입니다."
rows["101:956274266"]="정말 거북기술 전문성을 배워서 모든 레시피를 잃고 싶니?"
rows["101:98126625"]="이 군대는 불타는 군단 모든 곳에서 공격하고 있습니다 아제로스영웅이 필요해"
rows["101:987705858"]="높은 기술공 메카토르크가 오고 있습니다. \" ⁇ 의 탭\" 시상식은 몇 분 후에 시작됩니다!"
rows["101:988571619"]="우리의 길은 거룩하다. 우리는 토림을 떠나서 리치 왕의 동종들과 함께하기 전에 죽음을 선택하겠다."
rows["101:989824284"]="왜 이렇게 오래 걸리지? 너희 주인이 약속한 대로라면, 네놈들이 도와주면 의식이 더 빨리 진행돼야 하는데!"
rows["102:1011944533"]="괜한 애쓰지 마라, 타우렌 애송이. 스톰후프도 네놈도, 그리고 네 친구 어느 누구도 나를 가로막을 수 없다."
rows["102:101934442"]="넌 날 쫓는 걸 멈추지 않을 거야?"
rows["102:1022542728"]="클라시들이 나와 얘기해줘요, 공의회, 제국의 의도를 들어봤습니다."
rows["102:1032929668"]="우리 적인 테르마플러그가 그놈레건의 나머지 지역에 계속 힘을 기울일 수 없게 해서는 안 됩니다."
rows["102:1034459003"]="|TInterface\\Icons\\ability_whirlwind.blp:10|t OMG 나는 캐스팅 |cFFFF0000|Hspell:88481|h[오버드라이브]|h|r!"
rows["102:1051921048"]="지금 보아라, 모든 희생은 영세계와의 유대감을 강화시킬 거야"
rows["102:1061571598"]="제피르는 당신의 움직임을 증가시킵니다. 이 효과를 보수 하오 프램 루와 공유해 주시면, 그의 옆으로 걸어갈 수 있습니다."
rows["102:1066570448"]="이교도들이 제가 가졌던 전부를 빼앗아 갔습니다만, 저를 붙잡고 있던 자에게서 구한 이 부적은 당신께 드리고 싶습니다."
rows["102:1088096866"]="아빠는 항상 물고기가 수영하고 새가 날 수 있다고 말했죠."
rows["102:1120296989"]="토양의 해마트는 볼더크래그 뒤에 연합되어 있습니다. 우리는 마지막까지 로켄의 하역들을 반대할 것입니다."
rows["102:1142457147"]="내 경비병들을 꺾었다고 아주 기고만장을 하는구나. 우리 계획에 타협이란 없다!"
rows["102:115028590"]="폭발보다 더 좋은 것은 무엇인가? 많은 폭발이 있습니다. 이 모퉁이에 우리는 빅 바다 붐을 가지고 있습니다!!"
rows["102:1151717422"]="스스로에게 물어보세요. \"안전\" 밸브가 계속 작동한다면 어떤 의미가 있을까요?"
rows["102:1162205526"]="우리들처럼. 우리의 부상자 수가 얼마나 많는지, 얼마나 많은 사람들이 포로로 잡혔는지 기억하지 않습니까?"
rows["102:1200653525"]="가장 어두운 시대 에, 인내심 과 안심 한 손 이 가장 큰 가치 를 지니고 있는 것 이다."
rows["102:1215548059"]="정말 그노미스 공학 전문성을 배워서 관련 레시피를 잃고 싶니?"
rows["102:1218255839"]="내가 틀리지 않는 한, 워치프의 명시적 규정은 모든 전염병을 사용하도록 금지하고 있습니다."
rows["102:1241093819"]="아제로스는 너무 오랫동안 우리 그림자 아래 그 몸을 숨겨 왔느니! 이제 불타는 군단의 힘을 보여 주마. 절망을 맛보거라!"
rows["102:126226531"]="지구 반지는 임시적으로 침략을 막아줄 거야"
rows["102:126369301"]="폐가 터지고 팔이 아프기 전까지 연습해, 그 다음부터 시작하겠습니다!"
rows["102:1264391873"]="다른 방법이 없어 가로쉬를 여기서 막아야 돼 그렇지 않으면 평생 도망쳐야 돼"
rows["102:1265871736"]="누가 이 사람? 왕자라고 하셨나요? 어린아이가요. 아, 하지만 그는 어린 시절을 가지지 않았습니다."
rows["102:1296822366"]="우리는 조심스럽게 움직여야 합니다. 샤네족은 아직 완전히 이해하지 못하는 암흑 마술을 실천합니다."
rows["102:1297901961"]="마구스 무역 거래소는 달라란 북서부에 위치하고 있으며 도시의 대부분의 직업 훈련자를 보유하고 있습니다."
rows["102:1302423014"]="...고대의 악인을 보내면서 널 지켜보고 싶어서"
rows["102:1318461304"]="나즈그림은 위대한 지도자이자 훌륭한 전사였는데 그는 자신의 목숨을 넘어서서"
rows["102:1319911772"]="두려움은 무한한 마음에서 발돋움한다. 나를 쳐다보게 하지 마! 내가 견딜 수 없는 것을 보았어!"
rows["102:1325415991"]="드디어 손자들에게 이야기 할 이야기가 있어요... 왕국의 배신자가 우리 사이에 살고 있었다는 것!"
rows["102:1328231783"]="포위 무기를 활으로 쏘아 올려야 해"
rows["102:134395866"]="오크족 부관이던 흑마법사의 시체에서 이 물건을 얻었소이다. 이 물건은 오크들의 고향에서 온 것이오."
rows["102:1348195984"]="문이 열리는 것을 목격한 것은... 내 자녀들의 아이들에게 전해 줄 이야기입니다."
rows["102:1371819173"]="우리 애들의 생명을 꺾고, 그들의 길을 걸는 모든 사람을 죽이는 것을 기다리고 있습니다.\010"
rows["102:1376045474"]="텔스마르에서 카라반이 출발하고 있다는 소식이 들려왔어요"
rows["102:1384547335"]="명예의 계곡 북서부로 향해 보아라."
rows["102:1387985916"]="스 ⁇ 이 되는 건 어떤 것 같냐? 한 번 트롤을 만났는데 아버지는 그를 믿지 않지만, 그는 매우 현명해 보였다."
rows["102:1418131941"]="내가 군대를 데리고 스톤탈론 산으로 보냈는데 호드."
rows["102:1426711298"]="크레이터에 있는 모든 생물들이 카즈고로스의 작품이라고 말하는 거야?"
rows["102:1428063564"]="더는 기다릴 수 없다고 너희 지휘관에게 전해라! 대체 동맹을 맺을 생각이 있는 거냐 없는 거냐?"
rows["102:1449784740"]="대사님, 어떤 종류의 전력장을 활성화시켰습니다. 섬 전체의 제어탑이 켜져 있습니다."
rows["102:145164090"]="모두 알겠지만, 오크는\"록타르 오가르!\"라는 전투 함성을 내지른다. \"승리가 아니면 죽음을.\"이란 뜻이지. 지금 딱 맞는군."
rows["102:1473530847"]="넌 지구 반지랑이야, 난 네가 다른 사람들처럼 물 숨을 마칠 줄 알았어"
rows["102:1514118100"]="착상의 신비주의는 심각한 상처를 입은 모든 동맹을 치유하고"
rows["102:1517870925"]="|TInterface\\Icons\\spell_fire_firearmor.blp:20|t%s는 캐스팅을 시작한다|cFFFF9A20|Hspell:79582|h [바리어]!|r"
rows["102:1526906358"]="만약 우리가 썬더 킹을 무너뜨릴 수 있다면, 우리는 해운대에서 벗어나야 합니다. 이제 대담한 아이디어가 필요한 시간입니다!"
rows["102:1544089541"]="어린이주일 기념으로  ⁇ 차가 무료입니다. 서부 몰락지대!"
rows["102:1554051600"]="그래, 이제 내가 볼 수 있어 이 세상의 미래를 볼 수 있어 호드...내 호드."
rows["102:1556164919"]="오드리 버네프를 찾아라. 이 곳은 남북에 있는 코니어 구역에서, 호수변의 한옥 근처에 있습니다."
rows["102:1558273033"]="우리는 오랫동안 싸웠고 우리는 오그레가 믿을 수 있는 힘이라는 것을 반복해서 증명했습니다."
rows["102:1590527253"]="샤오하오처럼 우리는 우리의 궁극적인 운명은 땅과 하나가 되는 것임을 알고 있습니다."
rows["102:1604406742"]="폭탄은 우리가 좋아하는 폭탄이야 그래엄 반 타렌이 어떻게 만들지 알려줘"
rows["102:1607026647"]="안녕하세요, 친구, 내 바퀴를 이용하실 수 있습니다. 5개의 새벽의 사원으로 데려갈 것입니다."
rows["102:1615968631"]="허리 사이에는 몇 인치 더 커졌어, 동생아"
rows["102:1618064863"]="할로 끝이 끝나면, 우리는 이 모든 거북이를 찢어 버릴 거야"
rows["102:1618490497"]="불의 힘은 변화 속에서 있습니다. 그 힘은 상당히 있지만, 끊임없이 변하고 있습니다. 예측할 수 없습니다."
rows["102:1633580133"]="이 왕좌에서 나는 지옥의 명령을 내린다 그의 말씀은 생명이고 그의 말씀은 죽음이다"
rows["102:1650357401"]="환영합니다, 그리고 제 상품을 살펴볼 수 있습니다."
rows["102:1652809877"]="아치발드는 크로스보우의 마스터이고, 무기들의 마스터이기도 하다. 언더시티, 대 워 구에 위치하고 있습니다."
rows["102:1675580449"]="우린 그들을 배로 밀어 넣고, 그들의 폭발물을 훔쳐서"
rows["102:1686264625"]="스컬지가 이곳에서 저지른 일은 곧 세계 모든 곳에 영향을 미칠 겁니다. 놈들을 반드시 막아야 합니다!"
rows["102:1695584414"]="<아카네 수호자는 움직이지 않고, 당신이 어떤 전투 마스터를 의미하는지 설명하기를 기다리고 있습니다.>"
rows["102:1699061981"]="내 동생이 죽었지 내가 만난 적도 없는데"
rows["102:1713269285"]="드라크 타론에 대해 말해봐요"
rows["102:1717063850"]="이런! 그대가 낸 소리 때문에 원치 않는 이목을 끌게 된 것 같습니다!"
rows["102:1719403257"]="<농민은 먼 곳에서 눈을 돌리며 바닥을 쳐다본다.>$B$B그들은... 그들을 데려갔어.$B$B그들을 데려갔어요"
rows["102:1739570209"]="우리 포로들 중 한 장교가 있네 얼라이언스 여보!"
rows["102:1742799222"]="베레사 윈드런러와 만나라."
rows["102:1759358899"]="미미론의 인장을 회수하려면 자폭 장치 가동 후 폭발 전까지 미미론을 처치하십시오."
rows["102:1768687171"]="트윈 피크스에서 전투를 할 만큼 강하지 못해 더 많은 경험을 쌓은 후에 돌아와"
rows["102:1781418102"]="오, 당신은 그 스톰윈드 카운팅 하우스, 당신이 들어온 후 문에서 멀지 않습니다 스톰윈드."
rows["102:1798197718"]="테르조크가 널 보내면 거절해줘 내가 그에게로 돌아가지 않을 거야"
rows["102:1813443506"]="나는 나의 혈병들의 칼을 빌제덴의 패배와 실버문의 회복에 맹세한다.\010"
rows["102:1838365749"]="인내해, 리 리. 우리가 너무 빨리 판다리아를 탐험한다면, 우리는 빠르게 탐색할 파다리아를 다 잃게 될 것입니다."
rows["102:1838500072"]="이건 끔찍해요, 두라크! 지옥의 크림은 우리의 일 뒤에 악마가 있다고 확신합니다! 우리가 무엇을 할 수 있습니까?!"
rows["102:1847947654"]="비행선이 정박하고 대군주 사울팽이 뛰어내려 얼라이언스 병사들과 무라딘 앞에 섭니다."
rows["102:1850751731"]="먼저, 마을 사람들은 휴식을 필요로 합니다."
rows["102:1854516154"]="잘했어, 이 해적들에게 왜 우리 마을에 침투하지 말아야 하는지 가르쳐야 할 시간이야"
rows["102:185481832"]="이 지역에는 폭발하지 않은 공이 있을지도 몰라 최근 해안에서 많은 전투가 벌어지고 있어"
rows["102:1860294725"]="이 검은 그림자를 보아라! 스컬지의 그림자가 온 세상을 뒤덮었노라. 도망칠 곳은 어디에도 없다!"
rows["102:1866787843"]="아이언스토크는 트로그스가 죽기 전까지 아무도 내보내지 않을거야"
rows["102:1878320196"]="드래곤마우가 다시 위대해지길 원해요"
rows["102:1881703227"]="이 야영지에는 보급품이 넉넉하지 않다네. 그런데 문제까지 생긴다면 놈들로서는 정말 수치스러운 일일 거야."
rows["102:1898063805"]="루크가 모고를 꺾고 싶어 하지만 마을 사람들은 안전하지 않죠"
rows["102:1901266530"]="말퓨리온 스톰라이드가 사라진 후, 드루이드들은 혼란에 빠졌고 새로운 지도자가 절실히 필요했습니다."
rows["102:1915045808"]="여기서 내가 제일 똑똑하고, 강하고, 문화적인 골록이라고. 하지만, 감독은 전부 수세이가 하지... 이게 말이 된다고 생각해?"
rows["102:1915385694"]="또 다른 사람이 불을 지르고 전쟁무기를 만들게 될 겁니다."
rows["102:1916352117"]="난 끝의 시작이야 태양을 지워주는 그림자야 너의 운명을 알리는 벨"
rows["102:1943431176"]="아, 그래요, 그놈에 대해 들어봤어요.$b$b준비되면 데려갈 수 있어"
rows["102:1952210635"]="우린 이 물품을 이용해 모든 사람들을 전투에 준비해 줄 거야$B$B계속해, 앞으로 보자"
rows["102:1953260007"]="이 자이로 기어와 재고정 물림기어를 장착하여 유전자 재결합기를 작동시키겠네."
rows["102:1955259870"]="이 새로운 포세이큰 보통 어마어마하게 멍청한 사람들이죠."
rows["102:1963154793"]="%s는 함께 싸울 수 있는 목표를 찾을 수 없으므로 |cFFFF0000|Hspell:136854|h[Death Stare]|h|r로 리소트합니다!"
rows["102:1972074854"]="고마워요, 몇 시간 더 걸려서 돌에 휩쓸리지 못해"
rows["102:1973749925"]="\"사태: 로어키퍼 발드린은 약물을 마시고 자신의 삶의 본질을 주변 모든 NPC에 전달합니다\"."
rows["102:1976983992"]="정말 썩은, 썩은 물건이야. 땅 속으로 깊숙이 들어가서 모든 판다리아를 망칠 때까지 파괴해버리자!"
rows["102:1978654991"]="|TInterface\\Icons\\ability_warstomp.blp:20|t 갈레온은 |cFFFF0000|Hspell:121787|h[스톰프]|h|r!"
rows["102:1994769697"]="찢어진 무기와 갑옷을 입고 싸우지 마!"
rows["102:2022157609"]="자넬  ⁇ 과 뱀이 좀지લની 도움이 필요해요?"
rows["102:2034171234"]="젊은 인종들은 겨울 베일 때문에 큰 화제를 모으고 있습니다. 아이언포지의 은행은 축제의 중심입니다."
