rows["104:1576792550"]="돌 안에서 속삭이는 마음일 수도 있습니다.$B$B안녕하세요, 작은. 성전사에 대한 소식이 있습니까?"
rows["104:1581901054"]="이 영원한 꽃의 계곡은 점점 더 흥미롭게 되고"
rows["104:1608731057"]="정말 놀라워요. 그녀를 지배하면서도 여전히 스스로 자기 의식과 기능을 유지하게 하다니... 어떻게 한 거죠?"
rows["104:1643817110"]="매일 매일 우리는 이 광장에서 일만해 맙니다."
rows["104:165558666"]="아, 신비한 코도 소리로군. 난 코도가 땅을 울리는 게 참 좋단 말이야. 날 위해 그 짐승을 살펴봐 주게."
rows["104:170446795"]="배 준비해! 우리는 물과 함께 타고, 가장 부유하고 건강한 사람들이만 우리와 함께 할 수 있습니다!"
rows["104:1713164646"]="저는 이것이 더 작은 폭탄에 더 많은 폭발력을 넣을 수 있는 돌파구가 되기를 바랍니다."
rows["104:1719838371"]="치 지가 내 마음속으로 말하는 걸 듣는다$b$b내가 널 도와서 패빌리온 꼭대기에 올라갈 수 있어"
rows["104:1722000883"]="무슨 일이 있었지? 오... 머리가 폭발할 것 같네요."
rows["104:1725887643"]="오그릴라에서 내게 말을 하는 사람들은 당신이 가져온 정보에 매우 만족할 것입니다."
rows["104:1737530003"]="그들은 고통을 주는 것을 즐깁니다. 그들의 끔찍한 고문 수법은 악몽과도 같습니다."
rows["104:1748746979"]="왜 문 닫았는지 모르겠어 영웅들 내 무리가 이미 고드프리를 돌봐야 했어"
rows["104:175224142"]="오크 - 진정한 오크 전사 - 한 가지만을 원한다. 증오된 적과 전투에서 영광스럽게 죽기를 원합니다.\010"
rows["104:1753523805"]="|TInterface\\Icons\\spell_fire_twilightfire.blp:20|t%s는 |cFFFF0000|Hspell:86059|h[Deep Breath]|h|r를 취합니다!"
rows["104:1777054804"]="<보시가 귀하게 머리를 낮추고, 거의 당신의 요청의 중력과 의미를 이해한다고 한다.>"
rows["104:1794936373"]="골짜기가 문을 열기 전부터 우리는 채소를 북쪽으로 파고 보내왔습니다."
rows["104:1812716684"]="그대의 도움이 없었다면 리치 왕이 만들어 낸 끔찍한 괴물들 틈에서 영원히 죽지 못하는 저주받은 삶을 살았을 것입니다."
rows["104:1818757172"]="타드로스 경호님, 시라와 다른 사람들을 보내서 탑을 잡으실 수 있도록 도와주세요."
rows["104:1820626263"]="불, 내 사랑은 불로 변해 버렸어. 내가 두려워했던 것은... 그를 다시 찾기 위해서는"
rows["104:1826567533"]="감히 날 쫓아내겠다고!? 허우대만 멀쩡한 스톰윈드의 골 빈 녀석들에게 이 나이비의 진정한 힘을 보여줘야겠군! 두고 봐!"
rows["104:182998104"]="일리단 님, 이 오크가 저와 다른 이들이 이야기하던 용아귀 부족의 용사입니다. 이 용사가 우리에게 승리를 가져다줄 것입니다!"
rows["104:1836202182"]="그렇게 둘 것 같으냐! 죽어서 네놈의 노예가 되게 하느니 차라리 내 손으로 죽일 것이다!"
rows["104:1842894268"]="그 대량에 대하여 보라 너희는 두려워 하지 않느뇨"
rows["104:1865281952"]="파란 새가 큰 말이야, 내려와서 이 벌레를 흙에서 뽑아낼 수 있는지 봐!"
rows["104:1868240828"]="내가 여기 남아서 이 땅을 지켜볼게"
rows["104:186907559"]="난 다시는 누군가를 볼 수 없을 거라고 생각했어$B$B나 여기서 나가야 돼!"
rows["104:1875726919"]="지, 미안해 이제 같이 있을 수 있어 제발  ⁇ 으로 돌아가서 죽지 마"
rows["104:1881645326"]="계속 이동하면 자이나가 우리를 잡을 거야 다음엔 좀 조심해"
rows["104:1888725646"]="자, 이제 당신의 사과가 다른 사람들에게 팔릴 것이고, 그들은 잘 갈라질 것입니다!"
rows["104:191963667"]="난 영원한 불이야 되살아난 자 그리고 나는 될 것이다 빛 추운 시중에 너희를 인도하리니"
rows["104:1932344848"]="이 곳은 침투되어 있어... 우리는 이 곳에서 유물을 최대한 빨리 가져가야 합니다."
rows["104:1934446663"]="볼진 장군님, 우리가 이렇게 무례하게 방해되기 전에 당신은 우리에게 잔다라리 계획에 대해 말씀하셨어요. "
rows["104:1955740731"]="내 인생에 가치를 두면 다음 말을 조심스럽게 선택해$B$B침묵이 얼마나 현명하냐? 이제 스컬지를 파괴하라!"
rows["104:1968886202"]="내가 이끼를 가지고 왔는데, 운이 좋은 사람이 충분히 사고도 되면, 나는 그들에게 물건을 팔을 정도로 현명해진다."
rows["104:1978408377"]="함께 우리는 얼라이언스를 파괴하고 우리의 권리를 주장합니다."
rows["104:1978594473"]="너무 미안해, 얼마나 부끄럽지 몰랐어요... 제발 좀 더 쉬세요."
rows["104:1987114262"]="그 결심을 되돌릴 순 없겠군. 우리가 성심을 다해 자네를 영혼의 세계로 인도하겠네."
rows["104:1999251796"]="|TInterface\\Icons\\ability_druid_typhoon:20|t%s는 |cFFFF0000|Hspell:143559|h[다크 명상]|h|r에 들어가 있습니다!"
rows["104:2005152785"]="여기 갓린이 운영하는 은행이 있는데 서부 하천에서 있는 칸트립스 앤 크라우스 타버너 북쪽에 있습니다."
rows["104:201100471"]="당신이 묘사한 사람이 여기 있었고 그는 미스터리한 물체들을 나열하도록 설득하려고 했습니다."
rows["104:2021336249"]="저 감옥에서 구출하지 않았다면, 지금쯤은 전 죽었을 겁니다.$b$b난 잊지 않았어..."
rows["104:202643541"]="하늘로 봐 얼라이언스 눈, 썬더 클레프트에서 보자 지옥의 눈은 네 쪽에 있다"
rows["104:2029871996"]="내가 할 일이 너무 많지만, 나 혼자 할 시간이 없어."
rows["104:207001587"]="노먼 호네는 상류 구역의 상류 반지의 호네라고 부르는 벽에 먼지가 뚫린 균열을 가지고 있습니다."
rows["104:2071527176"]="제 경, 우리 신조들의 얼라이언스 권력 구조의 침투와 통제가 잘 진행되고 있습니다."
rows["104:2087380048"]="떠나기 전에 페이 리와 대화를 나누는 것을 잊지 마세요."
rows["104:2105404105"]="내가 힐다의 비서일 뿐이야 할 수 있는 게 별로 없어"
rows["104:2106501"]="하지만 내 인생에 작은 부분이 없어진 것 같아"
rows["104:2117677964"]="안 돼, 연습을 그만둬 내가 연습을 그만둘 준비가 되면!"
rows["104:2128877104"]="이 개구리 가 너 대신 말합니까?"
rows["104:2139905810"]="네르겔드는 바르굴에 힘입어 새로운 육신 거대군 중 첫 번째입니다."
rows["104:2144307073"]="내가 너희 무용한 스키들을 팀에서 쫓아내고 경비대에서 내버려둬야겠어!"
rows["104:25496473"]="죽은 자들의 영혼은 저주받고 고문을 당한다 내가 감염되면"
rows["104:270868649"]="하지만 시도조차 하지 않으면 모든 것을 잃을 게다. 드라카리는 그들의 신과 자신을 모두 죽이게 될 것이다!"
rows["104:282121710"]="왜 나한테 얘기하는 거야?$B$B네 자들과 어울려"
rows["104:284073529"]="하지만 이 전쟁은 적발적으로 프로토콜을 따르지 않는 지도자가 벌인 전쟁으로 우리 민족이 더욱 빨리 멸망하게 되었습니다."
rows["104:293306050"]="이 이상한 새로운 땅은 약초와 치료제 형태로 많은 것을 제공합니다."
rows["104:300440505"]="이 고드프리는 정말 특별한 사람이야."
rows["104:304790340"]="우리들을 흙에 심어 냈어요!"
rows["104:315897933"]="오늘 바쁜 날인데, 적어도 10명이 줄을 서 있는 걸 보여드리죠."
rows["104:319161809"]="내가 정신과학자니까 너보다 똑똑한 거야"
rows["104:335290119"]="멀리서 총기 발사 소리가 들리고, 그 다음에는 위에서 휘파람하는 공의 소리도 들려온다."
rows["104:386830508"]="싸구려 술이나 파는 저런 녀석들이 떠들썩하게 자기들만의 축제를 벌이는 꼴을 여기 숨어서 지켜보기만 할 텐가?"
rows["104:389092963"]="잘 해, 영웅들. 우리가 남겨둔 포털을 통해 돌아가 봅시다. 아이언포지."
rows["104:429311626"]="배신과 다른 배신 행위로 사형수색 중인 호드!$B$B모든 상금은 고르트 대장이 지불한 겁니다"
rows["104:431018724"]="우리 가문은 고대인들이 지정한 길을 따르고 있습니다. 우리는 다른 모든 것보다 왕의 은총을 받을 자격이 있습니다!"
rows["104:453792128"]="아이언포지 겨울의 성패의 축제 때 나무 밑에 모든 사람들에게 장난감을 남기고 있습니다!"
rows["104:463206241"]="그는 단지 병역에서 넘어왔다.$b$b난 도움을 구해줬지만, 경비자들은 날 쳐다보지 않더군요!"
rows["104:464576911"]="내가 왔을 때 다행이야!$b$b그  ⁇ 츠의 마지막을 본 적 없어"
rows["104:468447592"]="잘 봤지만, 미래에는 키린 토르와의 관계를 이용하지 못하겠소"
rows["104:482124723"]="오늘 밤, 이 자리를 찾아주신 모든 여러분께 감사드립니다. 샤트라스 최고의 희극 배우 페리 가트너를 박수로 맞아주시기 바랍니다!"
rows["104:491092466"]="어린 인종, 아기, 인간, 오크, 왜성, 하카리족을 물리치고 신들을 파괴할 수 있다고 생각하십니까?"
rows["104:501287016"]="새 날이 떠오르고 있습니다. 곧 아조엘네루브의 무사 군대가 일어나 이 세상을 정복하게 될 것입니다."
rows["104:501492889"]="전 전투에서 은퇴해서 가족과 평화롭게 살았습니다."
rows["104:501819905"]="네가 뭘 하는지 몰라, 볼더거트 나를 포로로 잡아두면 디폴름과 우리 모두를 멸망시키게 돼"
rows["104:508598843"]="<칼더의 입에서  ⁇ 이 튀어나와 빈 눈물로 그의 두개골에 돌아다녔다.>"
rows["104:511880799"]="몇 년 전에 낚아냈는데, 그녀처럼 생겼어요."
rows["104:513657559"]="살살라비름이 보내준 건 빚을 갚아야 해"
rows["104:543938030"]="이제 보아, 초갈 내가 너를 찾아오겠다 다른 사람들이 지켜보는 동안 네 머리를 찢어 버릴 거야"
rows["104:554396356"]="그들은... 퇴화하고 있습니다. 형제 여러분, 여러분의 노력을 재생하십시오! 그들이 돌아올 때까지 의식을 완료해야합니다!"
rows["104:556049984"]="내가 가르쳐주는 것들이 뇌를 젤리로 만들죠. 충분히 배워서 다시 오세요!"
rows["104:560942316"]="전투에서 부상자를 돌보는 사람은 너무 적어서 내가 능력이 있다면, 나는 확실히 그들과 함께 할 것이다."
rows["104:566682561"]="난 가로쉬에 대한 사랑도 없다, 그 많은 것은 확실하지만 호드을 떠나는 것은 내가 가볍게 하는 결정이 아니다."
rows["104:587168454"]="우리 총기 훈련사는 썬더 블러프의 낮은 중앙 상승의 타우렌 무기 마스터인 안세크와입니다."
rows["104:591991325"]="여러분들 모르겠지만 10마자 돌을 돌려주기 위해 만든 그  ⁇ 류 고기 헬멧은 정말 멋져 보입니다!"
rows["104:596915982"]=" ⁇  삼촌이 여기 걸어서 탐험하는 것보다 맥주를 마시고 앉을 것을 더 좋아할 것 같다는 건 믿기지 않네!"
rows["104:597038282"]="메이위키, 제 잔다라 아우거의 벨트를 가지고 도망친 작은 괴물"
rows["104:602327455"]="내 인생에서 최악의 해였어 테라모르가 파괴됐고 키린토르의 배신도 있었지"
rows["104:609959359"]="우리는 돈을 갚을 것입니다 얼라이언스 그들의 배신에 대해 천번이나 더하여 주옵소서 우리는 결코 용서하지 않거나 잊지 않을 것입니다"
rows["104:622731718"]="왜 다른 용이랑 다르게 생겼어? 맘만 먹으면 크고 늙은 용으로 변신하는 거야?"
rows["104:630713332"]="우린 죽을 때까지 싸우고 있어, 파오리스 우리 인종은 이 땅을 지키기 위해 만들어졌어"
rows["104:639546980"]="호랑이의 눈이란 어떤 사람이 말하는 걸 모르겠지만 호랑이의 손톱을 사용하는 방법을 보여줄 수 있습니다."
rows["104:648163335"]="이 트랜스마이터는 생존의 열쇠입니다. 우리가 완전히 작동하지 못하면 우리는 확실히 괴로워!"
rows["104:650693481"]="우리는 큰 숲을 존중하고, 지구의 선물의 기적을 위해 여기에 왔습니다."
rows["104:659102403"]="지금, 샤트라스에 타우렌 족장들을 모셨습니다! 그들이 매시간 정각에 세상의 끝 선술집에서 펼치는 멋진 공연에 여러분 모두를 초대합니다!"
rows["104:659861664"]="너희들은 비방한 겁쟁이들이야, 오크들아 너흰 분노한 개들 뿐이야"
rows["104:664709444"]="그건 말도 안 되는 명령이니 거부할 수 있소. 의심 가는 음식이라고? 그 말대로라면 벨패스트부터 체포해야 할 것이오!"
rows["104:676707518"]="카자로 산 꼭대기에 로맨틱한 피크닉을 할 수 있을까요?$B$B내 좋아하는 샴페인 좀 가져가라!"
rows["104:706589886"]="아니, 다른  ⁇ 이야. \010예, 저는 수도원이지만 항상 악마 사냥꾼이 되고 싶었습니다."
rows["104:711690930"]="아이사, 이건 유일한 선택지. 우리는 배를 날려 놓고 그 상처를 치유합니다."
