rows["105:750707439"]="저는 빌그워터 카르텔의 수익을 줄이는 음식 저장이라는 끔찍한 문제를 끝낼 것입니다!"
rows["105:757858442"]="그거 위험한 생각의 가지로구려. 어떤 일이 정말 잘못되었다면, 소리도르미 님께서 첫 번째로 아시게 될 것이오."
rows["105:769938521"]="당신께서 드락타론에 오신 이래, 주인님께서는 언젠가는 당신이 여기 올라와 주인님과 함께할 거라고 종종 말씀하셨죠."
rows["105:794631709"]="왜 우리 모두에게 부탁을 안하고 무기 보관소에 물건을 내려놓지?"
rows["105:796872806"]="글쎄... 그냥 내 생각인데... 네가 조금 더 짧은 것 같아. 그러니까 그 지뢰를 터뜨릴 확률이 더 낮다는 거지."
rows["105:80644360"]="웬 놈들이 감히 여길? 정신 차려라, 형제들아! 녀석들을 처치하면 거하게 한 상 차려 주마!"
rows["105:811697538"]="만일 너희가 부패를 물리치고 싶다면 먼저 너희 안에 있는 부패를 깨끗하게 해야 한다."
rows["105:811866858"]="무쇠 드워프들이... 사방에 깔렸군요... 저들은 지금 아래로 점점 내려오고 있습니다. 정말 악착같은 존재들입니다."
rows["105:817079017"]="여기 보이는 유적은 몇 달 전에 발굴한 것과 동일하지만, 물가 넘어서서요!"
rows["105:823733936"]="만약 그가 아버지와 비슷하다면 마하르와의 동맹은 호드에 새로운 시대가 시작될 것입니다."
rows["105:826226197"]="에노하르는 우리에게 몇 배럴 맥주를 주려고 할 것 같다고 생각하니?"
