rows["105:848539225"]="아서스, 순식간에 끝내주마. 그동안 너는 무수히 많은 생명을 고통스럽게 빼앗아왔지만 말이다."
rows["105:848993566"]="프로스트울프 포스에 이르는 경로를 순찰해 줄게"
rows["105:862511167"]="데즈코가 이 지역을 탐험하러 우리를 보내줬어"
rows["105:875345424"]="은행에 접근하기 위해 적절한 서류를 작성하고 적절한 수수료를 지불했나요?"
rows["105:888902055"]="하지만 그 후, 악의 어두운 거미들은 악의 눈과 다리 가득한 악의 겹에서 일어났다."
rows["105:890514805"]="강아지들이 마지막으로 공격했을 때, 수홀루가 그들을 쫓아 캠프까지 갔어요!"
rows["105:89249856"]="우리 가족 에서 여러 세대가 마법 을 배웠어요. 제 아들 이 지금 하고 있는 것 처럼 어릴 적부터 배웠어요."
