rows["105:936425148"]="바보여, 내가 죽인 걸 찾는데... 그는 이제 귀신이야. "
rows["105:937900474"]="난 순찰자하지만, 내가 좋아하든 싫든 리더십의 장막은 내 어깨에 떨어졌습니다."
