rows["105:99310730"]="안녕하세요, 고대인, 제가 요구한 모든 것을 해냈어요."
rows["105:995233656"]="기회가 된다면 우리는 호드에 합류해야 합니다. 스컬지은 우리 집단의 힘보다 더 떨어질 것입니다."
