rows["105:997872702"]="새 새야 날개로 큰 흰빛이 날 날개로 만든 크리에이터$B$B도와줘!$B$B안녕하세요!"
rows["106:100339437"]="참아라... 곧 좋은 기회가 다시 있을 것이다. 이번에는 티리온이 우리에게 갚을 빚이 생겼다는 것으로 만족하자."
