rows["106:1020901153"]="우편 상자 는 도시 전체 에 흩어져 있으며, 매매소, 은행 또는 숙소 앞 에서도 발견 할 수 있습니다."
rows["106:1023290733"]="우리의 방식은 최고의 서비스입니다. 저하륙선에서 미소적인 대화나 도전을 할 시간이 없습니다."
rows["106:103211392"]="썬더 블러프의 끔찍한 타우렌 스마시 후프스트롬도 환영합니다! 그 큰 어깨바닥을 보세요!"
rows["106:1035815284"]=" ⁇ 의 말을 기억해 보세요, 잘 기억하세요. \"당신의 친구들이 당신을 배신할 것입니다\"."
rows["106:1054731346"]="절대 선리버들을 믿지 말아요 그들은 아르헨티나 십자군 동맹군들의 눈앞에서 우리를 약화시키는 일을 열심히 하고 있습니다"
