rows["106:1070635534"]="네 빛이 꺼질 것이며 어둠이 너를 감싸고 그 안에서 움직이는 그림자를 두려워할 것이다."
rows["106:1073002802"]="%s]는 고백한다: 나는 몇 달 동안 Sunsong Ranch을 방문하지 않았다. 나는 모든 곳에서 허브와 버진을 상상할 수 있습니다."
