rows["106:1090445826"]="쓰레기통을 포장하고, 깔끔하게 배열해 놓은 것인데, 극심한 야만적인 것과는 달리"
rows["106:109916490"]="이 거칠게 말 그만해, 난 언더시티 밖에 일어나는 모든 일에 대해 맹인이라고 생각하십니까?"
