rows["106:711506917"]="난 피해자의 소리보다 더 좋아하는 게 없어요. 특히 제 피해자라면요."
rows["106:718669292"]="드디어 비행장까지! 고마워, 여기서 나갈 수 있어. 피즈크랑크에게 내가 돌아왔다고 말해줘!"
rows["106:720698792"]="내가 비밀을 알려주는 데 앞서 자기 가치를 증명해야 해"
rows["106:725079"]="너희들은 모두 쓸모없어, 네가 내게 공훈을 주는 경호가라도 이 작은 존재들을 내 궁전에서 막을 수 없다."
rows["106:729723558"]="고맙다, 친구들! 너희 덕분에 멋진 자료를 좀 얻었어! 자, 그걸 어디 뒀더라... 아, 여기 있군."
rows["106:742779885"]="내 인내심이  ⁇ 어지고 있어, 난 새 화살기 총을 네 가방에 넣었어"
rows["106:759459133"]="나도 네가 코타 피크의 위험을 견뎌내서 나와 함께 싸울 자격이 있다는 걸 알 수 있어"
rows["106:767226112"]="내 말부터 시작하지 마 시드, 대신 탑에 있는 내 방으로 보내줘"
rows["106:777575943"]="|cFFFFFFFF손가락은 함께 스톰파이크의 포착을 나타냅니다.|r"
rows["106:778003684"]="아르토르의 무살한 몸은 악마의 마법에 의해 공중에서 매달려 있습니다."
rows["106:77810599"]=" ⁇  발다르 북부 벙커는  ⁇  발다르 동부 입구를 보호합니다.$B$B얼라이언스에 의해 통제됩니다."
rows["106:791208557"]="방 중앙에 떠 있는 거대한 눈이 당신을 노려보기 시작합니다. 지금 당신은 고대의 신 앞에 서 있는 것입니다."
rows["106:804026899"]="제이나, 네가 믿었던 대로 동맹이 왔구나. 너희 모두 스컬지의 강력한 하수인이 되리라."
rows["106:807606241"]="애그라... 내가 드레너에서 태어나지 않았지만, 항상 우리 조상들의 전통을 존중하려고 노력해왔어."
rows["106:814460033"]="지금 제가 제공할 수 있는 최고의 의료서비스는 먼저 부상 예방을 위한 도구를 제공해주는 것입니다."
rows["106:823093763"]="빨간색은...  ⁇ 거리는 것과 연결돼 있습니다."
rows["106:847886475"]="그래서... 이것이 필사적이라는 느낌인가?\010<마브롤린의 호흡이 멈춘 후 질문이 사라집니다.>"
rows["106:857609700"]="내려와, 난 너의 날개를 어깨에서 찢어지고 흙으로 먹여"
rows["106:858714105"]="드래곤마우 씨, 항구를 되찾고 바다로 밀어넣어 호드!"
rows["106:868495937"]="피의머리 멤버들을 과소평가하지 마, 카이른이 들고 다니던 토테임을 본 적이 있어?"
rows["106:868601428"]="크라토크, 전 한때 무장수술가였는데, 대신 무장수술자의 방법을 배우고 싶었소."
rows["106:897382103"]="금속 의 마법적 인 특성 은 사라졌어요! 여전히 가공 할 수 있지만, 기존의 도금법 으로는 하지 않습니다."
rows["106:903467218"]="손님께서는 여기에 싸우러 오신 게 아니었으면 해요. 오늘은 거리에 분노한 사람들이 너무나 많더군요."
rows["106:903821556"]="다음 트롤이 방해하는 것에 대해 매우 불쾌한 놀라움이 있을 것입니다."
rows["106:90822116"]="여기 모든 곳에 빛나는!$b$b여기 파고 있는 걸 봐...$b$b숨을 쉬는 모자야!\010"
rows["106:926321082"]=" ⁇ 톤, 어둠의 기둥이 눈에 보이지 않는 것 이상으로 펼쳐져 있습니다."
rows["106:947019218"]="<너의 놀라움으로, 랩터 새끼는 당신과 소통할 수 있습니다.>$B$B배고프게... 그래서 배고프게"
rows["106:950370033"]="바닥에 있는 에너지 패드를 사용하여 아카네 피널을 올라가 길 위의 모든 기둥들을 만납니다."
rows["106:950687564"]="모든 장소가 잘 어울리지 않고, 우리가 할 수 있는 만큼 도움을 주려고 합니다. 하지만 소스는  ⁇ 루브입니다."
rows["106:974569417"]="어쩌면 당신은 고령이 했던 것보다 더 좋은 거북의 귀여운 고도크 유물을 다시 얻는 데 잘할지도 모릅니다!"
rows["106:979510032"]="그래, 그래, 어서 가서 겨울의 대부에게 겨울의 베일을 위해 원하는 것을 말해줘$B$B빨리 가자"
rows["106:991508247"]="만일 너희가 이 모든 것을 알고 싶어 한다면 그 답을 받을 준비가 되어 있을 때 너희에게 이르게 될 것이다."
rows["107:1002059643"]="정말 머리가 나쁘군요! 날 위협해서 보내려는 생각은 버리십시오, 탈레리스. 당장 내 눈앞에서 사라져줘요!"
rows["107:1006205180"]="스톰후프와 그의 일족들은 역사에서 완전히 사라지고, 이 땅은 원래 주인에게 되돌아갈 것이다!"
rows["107:1007504830"]="딸을 구해줬을 수도 있지만, 피를 제공하지 않았어"
rows["107:1020342055"]="네 적은 우리가 \"샤\"라고 부르는 어두운 에너지로 압도당해졌어"
rows["107:1023355990"]="영웅 여러분, 이 조각을 파괴할 때 어떻게 하시겠습니까?"
rows["107:1024654362"]="...하늘을 태운 불은 다시 돌아옵니다. 불타는 군단 찾을 거야 아제로스."
rows["107:1024798066"]="그늘숲의 여행자분들 반갑습니다! 어둠골에서 안토니오의 물건을 깜짝 공개합니다. 어서 서두르세요!"
rows["107:1045375767"]="기트들이 돌아오면 준비해줘요"
rows["107:1059798792"]="이 일은 훌륭합니다. 당신은 제 대신 임무를 수행할 준비가 되셨습니까?"
rows["107:1068632753"]="내 딸에 대한 사랑과 추억은 절대 잊을 수 없을 것이야. 이젠 정의의 이름으로 내 죄를 용서 받을 수 있기를 바라네."
rows["107:1070643530"]="하지만 잠깐, 이제 기억났어 넌 죽은자를 죽이는 법을 가르쳐줬잖아"
rows["107:1072051722"]="드  ⁇ 다라리는 당신이 본 적이 없는 힘을 가지고 있습니다."
rows["107:1104564661"]="네 썩은 일을 하러 보내줬어"
rows["107:1106407772"]="마키 귀족의 명예로운 끝... 그의 부족은 그가 마지막이 아니었다면 자랑스러워할 것입니다!"
rows["107:1119529304"]="그는 활빛 스펜러와 과부전된 가압기에 대해 계속 이야기합니다."
rows["107:1121720334"]="키건과 팬니는 서로가 한 사람으로 영원히 연합해지도록 여러분의 삶에 받아들이는 건가요?"
rows["107:1122926859"]="사라진 Harmonic Mallet, 바보 같은 이름이야"
rows["107:1133736373"]="스톤하스 벙커는 전투장의 동쪽 측면을 보호합니다.$B$B얼라이언스에 의해 통제됩니다."
rows["107:1144008646"]="스칼라와그 포인트가 바로 앞에 있어, 잠시 잠자리에 누워주겠네"
rows["107:1149774508"]="분노, 힘, 내가 평생 이렇게 강하다고 느끼지 못했어$B$B곧 드래곤마우 모두 나처럼 느껴질 거야"
rows["107:1195289814"]="삼촌은 우승하면 한 배를 가져왔고, 패배하면 두 배로 마시게 됐어요."
rows["107:1212334233"]="그럼 혼자만 견디지 않아도 되겠네 그냥 옆에 앉아서 잠시만간"
rows["107:1214372851"]="마지막 비전, 조상들이 우리 자녀들일 수 있을까요?"
rows["107:1220960647"]="그 곳에는 구단의 두개골이 보관되어 있습니다. 이 소소한 악마들은 내가 그것을 주장하는 것을 막지 않을 것입니다!"
rows["107:1222889877"]="우리가 할 수 있는 만큼 많은 사람들을 모아서, 우리를 쫓는 모든 워크겐은 생존자들을 쫓는 한 개의 워크겐이 더 적습니다!"
rows["107:1228255360"]="내가 원하는 건 도시 내 친구들을 방문하는 것 뿐이야. 난 이런 걸 원하지 않았어! 왜 호드가 우리에게 이렇게 해주는 거야?"
rows["107:1230168082"]="거대한 인간형 손자 인쇄가 지구 표면에 삽입되어 있습니다. 부드러운 녹색 빛은 내부에서 뛰는 것처럼 보입니다."
rows["107:1240755639"]="왜 화산이 있는 섬으로 로켓을 쏘아 올리는 거야?"
rows["107:1244157876"]="우리는 보통 동물의 육류를 먹지 않습니다. 하지만 우리의 곤경에 처해 있는 상황에서는 예외가 필요합니다."
rows["107:1250954211"]="우린 오랫동안 전쟁은 안했으니 우리 모두에게 좋은 일이면 곧 평화를 찾을 수 있기를 바랍니다."
rows["107:1264717381"]="저자와 비슷한 이들이 천 명도 넘게 있다네. 만 명이 넘을지도 몰라. 한 명이 사라지면 다른 이가 올라서서 그 자리를 차지할 것이네."
rows["107:127378133"]="이 거대기,  ⁇ 트라이저의 극성을 뒤집어 내보내야 해"
rows["107:1302624205"]="당신은 용기의 시험을 거쳤고 검은 황소의 길을 배웠습니다."
rows["107:1303357215"]="강력한 영적인 장벽으로 보호하고 있어, 우리 배가 착륙하기 전에 비활성화해야 할 겁니다."
rows["107:1303954723"]="우리가 어떤 식으로든 그 문제에 도움이 되려면 사람들이 더 필요할 것이네. 그 일을 도와줄 정찰병들을 불러들이도록 하게나."
rows["107:1328694329"]="브리벨스버프의 새로운 실리시우스 크런치 아이스크림을 맛보세요."
rows["107:1333108270"]="스톤하스 벙커는 전투장의 동쪽 측면을 보호합니다.$B$B이 둘 다 통제됩니다."
rows["107:1360157489"]=" ⁇ 은 몸무게의 5배를 지을 수 있어 절대 땀을 흘리지 않고 뛰어난 냄새를 맡는다."
rows["107:1360410141"]="경비자님, 그가 싸우고 있는 걸 보세요. 저는 더 잔인한 전사들을 본 적이 없습니다."
rows["107:1362382934"]="우리 군대를 즉시 위치로 데려가자, 토비아스 스키테는 포세이큰의 손에 떨어질 수 없다!!"
rows["107:1367341053"]="나는 여기서 버티며 가능한 한 시간을 벌겠다. 그 시간을 잘 써라. 우리 왕자님을 자랑스럽게 해드려라."
rows["107:1371259389"]="이 모고들은 여기 있는 것 같지 않아 오래된 유물을 파는 것 같지만, 파는 게 아니라 약탈하는 것 같다."
rows["107:1375977228"]="이곳에서 내 힘은 무한하다. 현실 법칙 따위 여기선 통하지 않아! 이 영역은, 내가 지배한다!"
rows["107:1382797363"]="트랄의 배신자들은 진정한 권력을 향한 길을 포기했습니다. 그들은 그들의 과도와 어리석은 것에 대해 죽어야 합니다!\010"
rows["107:1390993430"]="이 마을은 오치윈에 숨어있는 것보다 더 낫다"
rows["107:1392376529"]="파그우드에서 이렇게 많은 방문객이 없어요$b$b도와드릴까요?"
rows["107:1407047472"]="그리고 이제 네 괴물 친구들은 모두 안전하고 행복해졌고, 더 이상 해적들이 없어서 네 배를 폭발시킬 거야!"
rows["107:1407353669"]="기억해 두십시오. 두고 보면 아시겠지만 모든 사랑 얘기가 행복하게 끝나는 것은 아닙니다. 때로는 장미 가시처럼 아픈 것이 사랑이지요!"
rows["107:1417863150"]="호드은 이 전쟁을 더욱 격화시키기로 결심하고 그 대장도 내 고향을 바라보고 있습니다!"
rows["107:141890327"]="그의 아들 안드윈 윈도도 왕이었는데, 그는 내 나이에도 마찬가지였어."
rows["107:1422448189"]="트롤, 내 제안을 생각해봤어?"
rows["107:142534162"]="황후의 뜻은 우리 자신의 위대함, 그녀의 위대한 힘"
rows["107:1425518099"]="이 전투는 얼마 전부터 계속되고 있습니다. 이 불꽃이 다른 것보다 더 많은 싸움을 하고 있습니다."
rows["107:1460733098"]="워송 구치의 엘프들은  ⁇ 어 소리 내리고 잘  ⁇ 어 먹는다"
rows["107:1503910057"]="의심스러운 활동은 없지 군인님"
rows["107:1511837320"]="난 그 표정이 뭔지 알아. 내가 뭐라고 해도 안 되는 거겠지. 하지만 오빠가 또 죽으면..."
rows["107:1512324733"]="북부 로켓웨이 거래소에 오신 것을 환영합니다."
rows["107:1513626926"]="고원도에 걸쳐 있는 얼음 구덩이들은 가까이 가면 얼음의 본질을 줄 수 있습니다."
rows["107:1523415453"]="아래층에서 클라우드캐셔를 찾아 보석공작에 도움을 줄 수 있어야 합니다"
rows["107:155212820"]="손잡이, 머리와 기름은 네 뜻대로"
rows["107:1563217173"]="이 말은 내가 발꿈치 아래 두개골을  ⁇  때 느끼는 만족과 비교하면 아무것도 아닙니다."
rows["107:1575148959"]="|TInterface\\Icons\\ability_druid_tigersroar.blp:20|t%s는 |c0087CEFA|Hspell:98374|h[Cat]|h|r로 변환됩니다!"
rows["107:1590155156"]="이 악마들 중 일부는 한 번 이상의 직접적인 타격을 받아서 무너뜨릴 겁니다"
rows["107:1618462326"]="가오 삼촌이 지휘하고 다른 사람들은 벽 너머에 있어요"
rows["107:1622426419"]="계속 찾아봐, 레리쿼리, 우린 찾을 거야 호드 이승만, 뼈에 느껴요"
rows["107:1656124184"]="(오크 카트가 우고를 뒤집으려고 하는 종이 깨지고, 우고가 크게 콧물하고 깨어지지 않는 이벤트)"
rows["107:1663227362"]="숲 속의 조용하고 잠든 집들은 항상 꿈꾸고 있어"
rows["107:1664100381"]="에더 테크와 그의 승병은 바시르 착륙에 가자"
rows["107:1672635188"]="넌 습격에 참여했지, 하지만 모자가 벗겨져 있어."
rows["107:1702634183"]="|TInterface\\Icons\\spell_fire_windsofwoe:20|t%s는 캐스팅을 시작한다 |cFFF00000|Hspell:142306|h[나비된 지구]|h|r!"
rows["107:1707043692"]="|TInterface\\Icons\\inv_misc_volatilefire:20|t당신은 |cFFF00000|Hspell:139822|h[Cinders]|h|r와 고통 받고 있습니다!"
rows["107:170855257"]="그래, 어서 가서 겨울 할아버지에게 겨울 베일에 대해 원하는 것을 말해줘$B$B빨리 가자"
