rows["107:892662011"]="만약 반응제가 필요하다면, 당신은 올바른 곳에 왔어요."
rows["107:909379845"]="그 무리가 우리가 기대할 수 있는 것입니다. 조상들이 전투 전선에 돌입하기로 결정하면 우리를 도울 것입니다."
rows["107:953322678"]="제 기즈모틱 알마나코트론은 우리가 지난번보다 20초 더 많은 거비를 이길 수 있다고 말합니다!"
rows["107:962047159"]="저는 아버지의 유산을 이 곳에서 이어나가고 있다는 사실에 자랑스럽게 생각합니다.$b$b아직 성장하는 유산이라고 할 수 있습니다."
rows["107:974224129"]="다 됐어요! 아주 나쁘지는 않네요. 당신과 레이네가 이걸로 뭘 하려고 했다고요? 정말 강력한데요!!"
rows["107:995473627"]="멋지군! 참으로 경이적인 결과야! 차체 내구도 98.9 퍼센트라! 손상이라고 보기도 어렵지! 계속하자고."
