rows["109:1167569539"]="기회조차 없었다. 주위에서 동지들이 쓰러져갈 때, 가까스로 여기까지 도망쳐 와 입구를 막았다."
rows["109:1170411617"]="<당신은 약간 굽히지만, 영장이 계속하기 전에 눈을 좁히면서 움직임을 완료하지 않습니다.>"
rows["109:1183554000"]="이 황무지에서 많은 위험을 보았는데, 누가 알 수 있겠죠?"
rows["109:11955511"]="어린 뱀은 섬세한 물건입니다. 나쁜 습관이 형성되는 시기입니다. 좋은 훈련이 변화를 만들어줍니다."
rows["109:1199331299"]="모가들은 불안해졌고, 그 후 세대를 넘어서서,"
rows["109:1204279584"]="이 필멸의 존재가 그녀의 제단까지 가야 한다. 쉽지 않겠지. 어쩌면 불가능한 일일 수도 있다."
rows["109:1213163506"]="블러드하프 마을 동쪽에 큰 텐트가 있는데, 거기서 네르미 스카이캐저가 기다리고 있을 겁니다."
rows["109:1224000032"]="시간 없어, 소규모 팀을 보내자 우수한군으로 생존자와 소중한 화물을 구해줘"
rows["109:1230850565"]="우리 호수도 보셨나요? 너무 조용하고 조용한 것 같네요. 그렇게 좋아해요."
rows["109:1244888113"]="이 메달의 기억은 고통으로 뒤돌아다니고 있습니다."
rows["109:1245928972"]="여러분 중 몇몇은 이 남자를 기억할 수도 있습니다. 그는 깨졌지만, 오늘, 그는 당신을 깨고 싶어합니다!"
rows["109:1255559490"]="용감한 이들이여, 나랄렉스 님을 구하고 이 재앙을 끝내기 위해 에메랄드의 꿈으로 들어갈 때에 나를 지켜 주시오."
rows["109:1262621732"]="치 지의 도전을 받아들이기 위해 콩을 울라 네 천상의 도전 중 하나를 극복해야 한다"
rows["109:1269827934"]="마스터 피레노르는 트롤의 고성인 그로마시 홀드에서 지혜의 계곡에 있는 자문자들 사이에서 발견될 수 있습니다."
rows["109:1284997101"]="우리는 모두 샤의 영향에 맞서 우리의 마음을 강화하도록 훈련받았지만, 그것은 우리가 상상했던 것보다 강하다."
rows["109:1299524718"]="우리 가족은 10년 동안 자드와 보석을 만들어 왔습니다. 제가 여러분에게 가르쳐 줄 수 있는 것은 놀라실지도 모릅니다."
rows["109:1302852299"]="노래하는 수영장의 잔은 온 땅에서 가장 단단하지만 내 강한 눈앞의 공기와 같습니다."
rows["109:1303497495"]="그녀의 금 가방은 우편에 있어야 해요. 내가 일하면서 누군가에게 돈을 모으는 건 모욕적인 일이죠."
rows["109:1307034703"]="스켈레탈 하스 라이딩의 가장 세련된 점을 가르쳐 줄 수 있어요. 수업을 받을 수 있는 금이 충분하다면요!"
rows["109:1323414295"]="더 많이 왔어, 미안해, 이번에는 더 강한 술이 섞여 있어!"
rows["109:1333217975"]="프로스트모른을 통해 아타스는 자신의 아버지를 죽이고 이 땅을 파괴했고 그 모든 생명체와 함께"
rows["109:1334948225"]="|TINTERFACE\\ICONS\\Spell_Frost_WindWalkOn.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:87770|h[wind burst]|h|r!"
rows["109:1343961132"]="모닝듀 장로가 피즐과 포지크의 스피드바지인 천개의 바늘에 있는 혼란을 지켜보고 있습니다."
rows["109:1354001796"]="그들은 모두 자기들만을 위해 원했지만, 나중에 방문할 때 내가 널 죽일만큼 쉽게 그들을 죽였어."
rows["109:1354469407"]="호드와 얼라이언스 놈들에게 교훈을 가르쳐 줘야겠다. 평생 잊지 못할 교훈으로!"
rows["109:1379213549"]="저희에게 진실을 보는 능력을 허락하소서. 흉악한 자가 저희 사이를 배회한다면, 인도하사 정의를 찾게 하소서."
rows["109:1383096481"]="신께 감사해요... 난 파이어보우 스투트의 비밀이 나와 함께 죽을 거라고 생각했어요."
rows["109:1388057489"]="저는 탐험가연맹의 고고학자입니다."
rows["109:1390425339"]="미친 아버지의 집은 그의 주위에 무너지는 동안 남은 몇 명의 블랙 드래곤은 숨어들었습니다."
rows["109:139553890"]="브로그는  ⁇ 돌이 거긴 그를 여기 있게 해준다고 기뻐하지만 가끔은 그들이 웃는 소리를 듣다고 생각하죠"
rows["109:1411235470"]="[우측 클릭] 훈련자의 무기를 준비하기 위해\010가방 열기 위한 기본 키는 [B]"
rows["109:1411652962"]="나 때문에 마음 아파하지 마세요, 내 사랑. 당신은 나를 속박에서 자유롭게 해주었고... 이제 저는 당신을 더욱 깊게 사랑하게 되었어요."
rows["109:1428936325"]="위대한 사건들은 종종 겸손한 시작을 가지고 있습니다. 생각해보세요: 조용한 연못. 여전히. 물은 유리판과 같습니다."
rows["109:142943405"]="울두어 안에 숨겨진 지혜와 지식은 상상해 보세요."
rows["109:1443686080"]="아포테카리움에서 발견할 겁니다. 이름들은 닥터 허버트 할세이, 닥터 마쉬입니다."
rows["109:1447176108"]="\"정말 그래, 난 스톤탈론 산에서 일을 맡아 밤 elf 쓰레기를 고칠 거야\"."
rows["109:146951307"]="이 도시를 떠나서 당신의 비참한 메시지를 가져오십시오. 당신은 더 이상 가짜 '예언'으로 시민들을 훔치지 않을 것입니다!"
rows["109:1488973957"]="신호를 전송할 힘이 없다. 서둘러라... 하늘 가까이에서... 힘이 깃든 장소를... 찾아라."
rows["109:1490285233"]="은행은 다르나서스의 조용한 도시에서 위치하고 있습니다."
rows["109:1506605150"]="지구 영들은 이 방에 많이 존재합니다. 결국 우리는 지하에서요?"
rows["109:1512696214"]="아나크를 죽여줘요 가족들에게 곤란해졌어요"
rows["109:1536120088"]="내가 실패하면 이 세상의 운명은 네 어깨에 달려 있을지도 몰라"
rows["109:154299195"]="강력한 무기와 멋진 재채로 영웅은 짐승들에게 분노를 불어넣었습니다."
rows["109:1553262568"]="다른 말이 있는 곳으로 데려가 줄게. 친구랑 함께 지내본 지 오래됐지? 아마 너희도 좋은 친구가 될 수 있을 거야."
rows["109:1570761965"]="이 외래인들이 서로 어떻게 증오하는지 보라! 그들은 전쟁에 대한 증오를 입고 무덤으로 가져갑니다."
rows["109:1571144505"]="달라란 아래에는 적어도 세 가지 길이 있습니다. 동쪽과 서쪽에서 하수 입구와 북쪽에서 우물."
rows["109:1572680090"]="남쪽에는 좋은 농장이 될 수 있는 한 절벽이 있습니다."
rows["109:1586064787"]="이세라는 나를 이리로 보내어 에시나의 야생 영혼과 접촉하도록$B$B하지만 고대인들은 침묵하고 있습니다."
rows["109:1591686506"]="다시 현장에 돌아간다는 건 좋네요. 스톰윈드에서 항상 갇혀있지 않은 것 처럼"
rows["109:1608610731"]="난 동물들을 진정시키려고 노력해"
rows["109:1624700395"]="여기 북쪽에서 다리 건너가 동굴이 있는데, 그 안에 있는 원자체를 죽일 수 있다면 폭풍은 멈춰야 합니다."
rows["109:1634020380"]="한 가지만 해야 돼 내가 해치야 돼"
rows["109:1634096356"]="나는 알타비름 만보자 라스타칸 왕의 사신이다$B$B제 교류는 사제, 마법사, 마녀와"
rows["109:1649885838"]="우리의 숫자는 무한하고, 우리의 힘은 헤아릴 수 없습니다. 파괴자에게 반대하는 모든 사람은 수천 명의 죽음을 맞이할 것입니다!"
rows["109:1665620017"]="프라이모르디우스 |cFFFF0000|Hspell:136209|h[개발]|h|r 및 승소 |cFFFF0000|Hspell:136225|h[파토겐샘]|h|r!"
rows["109:1682117164"]="더욱 의심스러워지는군. 시간의 실마리가 꼬이며 잘못된 무늬를 만들어내 버렸어. 하지만 어떻게 말인가?"
rows["109:1694224890"]="|TInterface\\Icons\\spell_nature_earthquake.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:83445|h[쇼크웨이브]!|h|r"
rows["109:171093366"]="미안하지만 제 기리폰을 타고 가서는 안 돼"
rows["109:1728829205"]="자네 아버지가 마신 그 피를 나도 마셨네, 가로쉬. 저주스러운 만노로스의 독이 내 혈관을 타고 요동쳤다네."
rows["109:1741361857"]="|TInterface\\Icons\\Ability_Siege_Engineer_Superheated.blp:20|t 활성 레이저 타워가 당신을  ⁇ 어!"
rows["109:1742308006"]="신은 호젠 도전에서 물러나려고 했지만, 우리는 두 배로 호젠을 당했고 그는 그로부터 물러나지 못했다."
rows["109:1744793087"]="아크니엄의 주인들을 찾고 있소?"
rows["109:1751769696"]="좋은 싸움을 해왔어, 영혼아, 몸의 힘과 마음의 힘을 내게 주라고 부탁한다."
rows["109:1757190710"]="이건 내가 아는 거야, 다른 놈들한테 도움을 요청해야 하는 실패한 괴물들과 거래하는 것보다 낫다"
rows["109:1766855634"]="매리스 치안대장님, 제 12 기병 연대 소속 하사관 키샨, 전투에서 돌아와 보고드립니다!"
rows["109:1798467162"]="이런디프 광산은 얼라이언스 영토에 있으며, 스톰파이크 묘역 북쪽에 있습니다.$B$B트로그족이 통제하고 있습니다."
rows["109:1799458389"]="바람을 타고 있는 마차의 뒷면에 앉으면 힘과 속도라는 명성을 잘 얻었다고 볼 수 있습니다."
rows["109:1816879086"]="넌 어디까지나 갈 수 없었어. 내가 쇼핑을 할 수 있는 진짜 괴물들을 찾았다는게 너무 다행이야."
rows["109:1824526886"]="아무도 공황하지 마, 이 불쌍한 섬에서 나가도록 하겠습니다."
rows["109:1834562288"]="불모의 땅, 뜨거운 태양과 적대적인 주민들과 함께, 당신의 힘과 강도를 시험하는 완벽한 장소입니다."
rows["109:1845106095"]="난 강렬한 츠, 아이언벨elly 몬크입니다."
rows["109:1846807927"]="오, 낯선 사람 안녕하세요. 난이도가 죄송합니다. 보통 이 곡물 보관소는 최고 수준의 효율적인 상태입니다."
rows["109:1857844334"]="아뇨, 정말 고통이 심해져서 의식이 사라질 겁니다."
rows["109:1858748854"]="배에 대해 조사하고 그 동물들을 처리하는 걸 봤어"
rows["109:1875682664"]="내 꿈은 언젠가 스푸터발프처럼 빛나는 사람이 되길 바라며"
rows["109:1876615936"]="(슈가 거대한 물구덩이를 주고 부고에게 뿌리는 사건이 일어나서 후쿠를 쫓아다니는 장면)"
rows["109:188845347"]="드래곤마우가 자유를 되찾을 수 있도록 도와줄게?$B$B자엘라와 얘기해줘요, 그녀는 저항을 조정하고 있어요!"
rows["109:1904161877"]="두개골의 덩어리는 불쾌한 냄새가 난다. 아라코아들이 최근에 덩어리에 추가한 것 같군요."
rows["109:1904185170"]="|TInterface\\Icons\\spell_frost_iceshard.blp:20|t 후오슈아프 캐스트 |cFFFF0000|Hspell:126321|h[냉장고 화살표]|h|r!"
rows["109:191069238"]="영광의 계곡에 있는 용맹의 홀에서 그레즈 래지피스트와 이야기해줘"
rows["109:1919999796"]="누군가가 이 잔과 화학 도구를 이용해 다양한 종류의 잠수함 연료에 대한 실험을 하고 있습니다."
rows["109:192280859"]="이 원주민들에게 전쟁을 전하는 것은 잘못된 것입니다. 우리는 그들에게 우리 자신의 최선의 것을 가르쳐야 합니다. 최악의 것이 아니라"
rows["109:1932058273"]="브루페스트를 잘 아는 오크들과 함께 축하해!"
rows["109:1933349128"]="날 따라오시오, 성기사 양반. 드워프 스타우트 맥주를 마시듯 빠르게 마갑을 완성해 주겠소. 음... 스타우트 맥주가 갑자기 먹고 싶은데..."
rows["109:1949706957"]="왜 오래된 모가들이 여기 파란 벽과 기둥을 짓지?"
rows["109:196829837"]="귀여운데, 똑똑한 연설을 할 수 있고 매력적인 모습을 보일 수 있는 여자에 관심이 있으세요?"
rows["109:1971342538"]="내 아들을 빼앗아갔어, 제 물건을 빼앗아갔어."
rows["109:1976840454"]="아쿠마이도 우리한테 옛 신들을 불러줄 거야"
rows["109:2011509751"]="이 요소들은 혼란스럽고 야생입니다. 학습을 통해서만 우리는 그들과 접촉하고 통제할 수 있습니다."
rows["109:2014036136"]="호드호는 우주선을 공격해서 테일드라실까지 도달하지 못했지만, 그게 시작이야"
rows["109:2022516440"]="어떻게 내가 Fizzcrank 내 목에 숨을 쉴 때 모든 물건 없이 아무것도 할 수 있을까?!"
rows["109:202864586"]="로탄 실버블레이드를 찾을 수 있는 곳이죠."
rows["109:2031518839"]="|TInterface\\Icons\\inv_misc_eye_04.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:96920|h[Occuc'thar의 눈]|h|r!"
rows["109:2040167402"]="시간의 흐름을 형성하는 것은 매우 어렵고 매우 섬세한 작업이지만 오늘 당신은 훌륭하게 수행했습니다."
rows["109:204813004"]="울다만 지식의 파수꾼에 대해 들은 얘기가 있는데, 어째 당신과 대단히 비슷하군요. 혹시 같은 역할을 하시나요?"
rows["109:2053183601"]="오, 이런. 이게 대체 무슨 냄새지... 잠깐. 하, 어이쿠! 제 감각이 돌아오려면 시간이 좀 걸리겠는데요."
rows["109:2054533479"]="자, 이 무작위 기구를 내려놓고 이 모든 것에서 벗어나자 아웃랜드."
rows["109:207430720"]="드디어 호숫골에 도착했군... 자, 모두 이리 와서 안토니오 페렐리의 물건을 싼값에 사 가세요!"
rows["109:2075125034"]="네, 네 챔피언들의 도움으로 어둠의 철은 던 모로그에서 잔다라리 위협을 끝낼 거야"
rows["109:2076229098"]="안개부름이는 제단의 힘으로 날씨를 참 잘 다스려. 어떤 수정을 사용하는지 그냥 안다니까! 정말 잘해!"
rows["109:2086848786"]="허브는 너무 비싸서 좀 더 필요해"
rows["109:2112412543"]="우미가 보낸 거 맞죠? 평소에 절 깜짝 놀라게 해 주겠다고 말했지만, 이런 것일 줄은 생각도 못 했어요!"
rows["109:2126161297"]="내 팔다리를 뻗는 건 정말 좋네요."
rows["109:2130978634"]="새로운 헨웨이 6000가 곧 집합선에서 내려올 것이라는 소식이 들었는데, 저는 흥분을 막아낼 수 없습니다!"
rows["109:2131183838"]="말도 안 되는 소린 그만해요. 배고파 죽겠다고요! 얼른 바다에 들어가서 먹을 거나 좀 잡아와요."
rows["109:2136375416"]="이 싸움은 내 시간을 낭비해줬어 넌 챔피언이 될 준비가 안 돼"
rows["109:2143257275"]="그녀는 쓰레기 속에 매달려 있고 난 증기압이 떨어졌어$B$B이 문제에서 우리를 풀어줄 수 있어?"
rows["109:22207998"]="질의를 시작합니다. 비상 안전장치 알갈론은 제1관리자 활동 정지 시 자동 실행되는 위급 신호입니다."
rows["109:229682954"]="이 래프트는 당신네 이웃이, 만약 당신이 래프팅을 하고 싶다면 여기로 돌아와"
rows["109:240359445"]="여러분께 주정뱅이 라리크를 소개합니다. 그의 어머니는 너무 뚱뚱해서 칼날 산맥으로 날아갈 때 요금을 두 배는 더 내야 한답니다!"
rows["109:249081497"]="니우자오의 도전을 받아들이기 위해 고롱을 울라 네 천상의 도전 중 하나를 극복해야 한다."
rows["109:260829518"]="이미 넘치는 잔을 채울 수 없으니 지혜가 되기 전에 빈 그릇이 되어야 합니다."
rows["109:285739752"]="오늘 우리는 우리 할머니의 이름으로 애도와 슬픔과 두려움을 가르칠 것입니다."
rows["109:289566832"]="여기는 덜떨어진 놈들만 있나? 내일 아침까지 새로운 역병 품종을 완벽하게 분석해서 보고하도록! 지금 당장 시작하게, 라비엔!"
rows["109:296133199"]="만약 당신이 여기로 오려고 한다면, 자신을 유용하게 사용하세요. 왜냐하면 그 곳의 그림자 추적자는 별로 일을 하지 않기 때문입니다."
rows["109:297981412"]="얼마나 불행한가!$b$b좀 정리해 보죠?$b$b이럴 필요가 있는 것보다 더 많은 것을 만들고 싶지 않을거야"
rows["109:311675098"]=" ⁇ 을 통해 날아다니는 죽음이 그의 손목에 와서는 악하고 평화로운 진주 암살자 Satay Byu!"
rows["109:341424194"]="전쟁원장이 지옥불 성 성을 침공하라고 명령했고, 우리는 이 노출된 성벽을 시작하게 될 겁니다."
rows["109:363208051"]="아쉬요, 넌 아직 어르신도 아니고, 진주도 되지 않아."
rows["109:367444754"]="이 흔적이 피가 흐르고, 그 길을 따라 근처의 한 벌목으로 가자"
rows["109:371480451"]="비행선으로 운반할 수 없는 물자는 여기까지 오려면 배로 길고 긴 노스렌드를 지나야 하네."
rows["109:385511925"]="우리가 이곳에 온 첫날 이 동굴을 발견했지요. 마법석의 힘을 유용하게 쓸 수 있을 거예요."
rows["109:405950730"]="시간이 되면, 서둘러서는 안 되는데, 우리의 호평은 무한히 당신에게 주어집니다."
rows["109:410081293"]="이 상자 문제 잊으려면 울담에서 온 사람들이 좋은 가격에 올릴 수 있어요"
rows["109:4266722"]="살아가기 위해 얼마나 멋진 날인가!"
rows["109:44862540"]="모두 감사합니다! 계속 박수를 쳐주세요. 아까부터 이 안에 파리 한 마리가 보였는데 여러분 중 한 분이 잡아주시면 좋겠네요! 좋은 밤 되십시오!"
rows["109:458040238"]="지지지는 항상 친구들을 때리는 데 잘했지만, 지지지는 여기 공부한 이후 훨씬 나아졌어요."
rows["109:461453277"]="야생의 영돌 보스가 나타나서 너한테 울고 있어"
rows["109:467631142"]="북쪽의 호수 근처에 야생 야크들이 많아서"
rows["109:473082215"]="아치발드는 크로스보우의 마스터입니다. 그는 전쟁 구역에 위치한 언더시티의 무기 마스터입니다."
rows["109:492498967"]="왜 내가 화살자라고 불리는지 알아내기 전에 내 시선을 벗어나"
rows["109:503750407"]="다델은 맥주를 만드는 기술을 잘 알고 서부 아저워치의 페티마와 긴밀히 협력하고 있습니다."
rows["109:527753201"]="두려움으로 이시, 적을 향해 돌봐 죽음이 오면"
rows["109:561478218"]="하나도 안 무섭다고! 덤벼! 앞발 두 개를 몽땅 꺼내서 할퀴어주마!"
rows["109:572542599"]="아, 속박에서 자유로워지다니 정말 기쁘군! 토그타르는 아직 풀어 주지 않았소? 인간들은 우리를 서로 다른 곳에 가둬 놨소."
rows["109:590342783"]="이 포세이큰들은 빠른 학생들인데, 오래된 개들에게 새로운 트릭을 가르쳐 줄 수 있을 것 같아요."
rows["109:597135276"]="그래서 당신은 그 곳에서 숨겨진 희귀하고 강력한 물질을 찾아내기 위해 쉐도우펀크 포스에 진입한 사람이야?"
rows["109:597429477"]="|TInterface\\Icons\\inv_misc_gem_stone_01:20|t%s가 |cFFFF0000|Hspell:126401|h[녹색 화석]|h|r로 변한다!"
rows["109:600663765"]="고성대 대장님이 도시 마녀 트레이너를 방문하고 있어"
rows["109:608407210"]="그래서 이웃이 머리를 자르고 옷을 입었지"
rows["109:608609388"]="이 땅을 잃는 자격이 있어, 네 사람들이 우리에게 한 짓 때문에!"
rows["109:609906565"]="프라이모르디우스 |cFFFF0000|Hspell:136209|h[개발]|h|r 및 승소 |cFFFF0000|Hspell:136245|h[메타볼성 증진]|h|r!"
rows["109:61700217"]="베스프리스투스, 테일드라실의 기지에서 오는 히포그리프들을 감시하는 사람이야"
rows["109:620797521"]="리치 왕의 세력이 이 비참한 사람의 시체를 보고 호드이 굴복하지 않을 것이라는 것을 알 수 있도록 해!"
rows["109:622006164"]="이 강아지들은 우리를 죽였지만 우린 여전히 평화를 제공해줬어"
rows["109:631214096"]="작지만, 당신이 뭘 하는지 알면 그 일을 해낼 수 있어"
rows["109:641663805"]="사우로크들은 최근 조용하고 불안해지면서 모고에 대항할 때가 됐습니다."
rows["109:647522072"]="내 아들 마리한테 확인해봐요, 그는 좋은 아이예요."
rows["109:649008799"]="오스틸 드 몬입니다. 한 차 근처에서 경비하고 있습니다."
rows["109:652839688"]="이번 대회가 끝나면 많은 반려동물을 치료할 것 같아요"
rows["109:687932827"]="가로쉬를 퇴치하기 위해 군대를 모이고 있지만 시간이 걸릴 것이고 왕자는 이미 위험에 처할 수도 있습니다."
rows["109:694561362"]="브랜은 거인과 동맹군이 공격했을 때 이 루닉 상징에 대한 가이드 작업을 하고 있다고 썼다."
rows["109:698306352"]="아내, 두 딸, 두 아들만 있어"
