rows["109:73097240"]="유일론의 도전을 받아들이기 위해 고그를 울라 네 천상의 도전 중 하나를 극복해야 한다"
rows["109:735867857"]="시간이야, 마법사! 다크스피어의 아들딸들이 돌아왔어."
rows["109:750310220"]="안녕하세요, 친구. 자, 이제 Grim Batol를 타고 죽음의 날개에 한 번의 타격을 해봅시다."
