rows["109:822515306"]="드래곤, 내 말 들어봐! 난 북녘골의 막시밀리안이고, 너를 구하러 왔어. 너의 피가 가득하네..."
rows["109:837780213"]="우린 채굴자, 농부, 공예가 아니라 군인이지만, 우리가 해야만 해도 헐뜯어먹어 지지를 방어할 것입니다."
