rows["10:999573408"]="상관없어"
rows["110:1017340820"]="우린 위에서 명령받았어 Rajaxx을 파괴해라"
rows["110:1043175725"]="넌 워크인을 그늘숲로 데려왔어, 어둠의 라이더들을 내 농장으로 데려갔어"
rows["110:1043752961"]="<거샤라는 당신 가까이 다가오면서 당신을 보고 옆으로 굴러오며 희망의 미소가 그의 얼굴에  ⁇ 어지는 것을 보게 됩니다.>"
rows["110:1045084845"]="이 빙하는 얼음왕관에서부터 흘러나오고 있군... 게다가 언데드까지 사방에 있다니! 여기는 학자께서 보실 때까지 그냥 두는 게 좋겠소!"
rows["110:1072663404"]="파하라드, 내가 방금 말했던 건 네가 마지막 블랙 드래곤이야"
rows["110:107641301"]="아니야. 아서스는 여기 없네. 아서스는 리치 왕의 마음 안에만 있는 존재야. 그것도 점점 희미해지지..."
rows["110:110649128"]="내 힘은 파괴적인데, 이 필사자들이 내 영역에 들어오는 건 말도 안 되는 일이야!\010"
rows["110:1108572125"]="이해해요, 침략을 기다려야 한다고 생각했었는데 당국이 떠나길 원한다면 우린 떠날 거야"
rows["110:1114507185"]="우리는 이 소문에 대한 진실을 밝혀내야 합니다. 그리고 우리들 사이에서 공포를 퍼뜨리는 Twilight의 Hammer 캠페인을 멈춰야 합니다!"
rows["110:1118914594"]="우리는 오늘, 그리고 우리 자신의 피로 - 아이언포지, 얼라이언스의 공의회에 대한 우리의 충성심을 증명할 것입니다."
rows["110:1119860056"]="경호가 필요해요, 만약 당신이 광장에서 복수를 원한다면, 텐그,"
rows["110:1148922518"]="다른 일이 있어,  ⁇ 무그한테는 걱정 마"
rows["110:1159483358"]="이건 field trip이 아니네, 거미! 넌 지금 아웃랜드에 있어!"
rows["110:1160392909"]="미안해 외래인, 공식적인 일을 하지 않으면 내가 도움이 될 수 없어"
rows["110:1163735757"]="이제 다시 일하자! 상사들은 위에서 바라보고 있고 그들은 무작위로 받아들이지 않는다!"
rows["110:1165449828"]="매너로트에 집중해 집중을 방해해야 해"
rows["110:116969450"]="우리는 스톰윈드 전체에서 건강한 꽃을 공급하는 유일한 공급자입니다. 우리는 모든 경우에 아름다운 꽃을 제공합니다."
rows["110:1184866690"]="죄송합니다만, 다른 볼일이 있어 이 자리를 떠나야 할 듯합니다. 다음에 또 찾아 주십시오."
rows["110:1187644198"]="지구 영들이 그린스톤 화석에 대해 불만을 갖고 있다고 들었어요"
rows["110:1193933281"]="하지만 이 경기를 지켜봐야만 경의 도움을 얻을 수 있다면, 자리를 지키겠소. 당장은 말이오."
