rows["111:604389635"]="북부 로켓웨이 터미널에 오신 것을 환영합니다. 당신은 아마도 잘못된 방향을 잡았지만, 어쨌든 당신을 가지고 있는 것이 좋습니다!"
rows["111:626692619"]="그럼 역사에 대한 당신의 지식을 시험해 보겠습니다. 타우르-아헤, 타우렌의 언어, 라'코루이란 무슨 뜻일까요?"
