rows["111:63573081"]="내가 남아서 티리온에게 우리의 진전을 알려야 해요. "
rows["111:640898858"]="귀여운 황제, 다 끝났어. 당신이 한때 싸웠던 어둠은 영원히 판다리아에서 깨끗해졌다."
rows["111:67425062"]="<사령관 경은 웃음으로 반짝이는 것인데, 당신을 고찰적으로 쳐다보고 있습니다.>$B$B그게 내가 듣고 싶은 거야"
