rows["112:1318679890"]="멍청한 크록. 우리 군대를 키워 주려고 사람들을 모아 왔군. 일어나라, 은빛십자군 용사들이여. 죽은 몸으로 리치 왕을 섬겨라!"
rows["112:1334983828"]=" ⁇ 드랄 스태겔름은 우리의 죄와 어리석은 짓의 짐을 들고 있고, 그렇게 함으로써 우리 모두의 존경을 받을 자격이 있습니다."
rows["112:1422198785"]="더 많은 것을 알고 싶다면 스톰윈드."
rows["112:1425216799"]="이 시간의 길은 현재 붕괴하여 재생성되었습니다. 그 결과는 옛날의 스트라솔름이었지요. 안에서 도대체 무슨 일이 일어나고 있었을까요?"
rows["112:1457028966"]="죽은 놈들은 이미 무너진 기둥이 주는 교훈을 깨달았을 테지. 교훈은 죽은 얼간이들이나 곱씹게 내버려 둬라. 이제 집으로 돌아간다."
rows["112:1462754958"]="보두로 수색자는 종종 하위 도시 상인의 시장에서 발견됩니다."
rows["112:149915157"]="그러니까 네놈이 리치 왕의 위대한 창조물들과 장난 칠 정도의 실력이 된다고 생각하나 보지? 람스타인. 가서 침입자들에게 따뜻한 환영 인사를 해 주고 오너라!"
rows["112:1501243294"]="가끔은 이 놀라운 도시가 완성될 꿈도 꾸지만, 이런 모든 일은 내 꿈을 악몽으로 바꾸어 놓았어요!"
rows["112:1501911032"]="시간이 우리 편이 아닐까봐 걱정해요, 일탈라인."
rows["112:1503345126"]="두 개의 경우 있습니다: 무역 구역의 상인당, 그리고 왜성 구역의 경매당 스톰윈드"
rows["112:1534876920"]="<볼코르의 몸은 움직이지 않고 있다. 당신이 멀리 이동하기 시작하면, 한 손이 손을 내밀고 발목을 잡는다. 그는 살아있다!>"
rows["112:1579156306"]="동물의 친구라면 내 친구일 거야 사냥꾼의 홀이 사냥꾼의 오르는 위에 있는 거야"
rows["112:1589369350"]="도저히 참을 수가 없군! 난 연합왕자를 대신해 이곳에 왔다. 기다리려고 온 게 아니란 말이다! 고라모쉬가 나를 기다려야 옳은 것 아닌가!"
rows["112:1602227006"]="더 훈련하러 왔나요? 그럼 길에서 먼지를 벗고, 일을 시작하자."
rows["112:1626700814"]="그리고 두 연인이 숨을 거둔 곳에 나무 한 그루가 자랐소. 엘프들은 그 나무를 사랑나무라고 부르지. 분명 서큐버스를 불러내는 자극제가 될 것이오."
rows["112:1665451564"]="우리는 많은 물품을 가지고 있지만, 우리는 여전히 더 많은 것을 필요로 합니다. 우리가 전투장에 수병을 보낼 수 있기 전에."
rows["112:1679467268"]="어떤 사람들은 그가 우리 민족을 비난하는 것처럼 보이는데, 그는 오래전 유동 모래 전쟁 때 그의 아들을 잃었다는 것입니다."
