rows["112:776547889"]="녹색 버튼을 누르면 어떨까요?"
rows["112:792855837"]="이 배는 새로운 경영자입니다."
rows["112:798130200"]="응답 코드를 다시 만들었다. 너희 행성은 유지될 것이다. 이제 나는 내 계산을 믿을 수가 없다."
rows["112:810391823"]="돈 벌어야 해요 아빠가 항상 말했듯이 전쟁 때보다 더 좋은 시간 없어요 "
rows["112:815077695"]="우리 모두에게 다행이 트롤은 우리의 아름다운 도시 안에서"
rows["112:818102550"]="이 곳에서 탈출하는 것은 내가 생각했던 것보다 더 힘들어$B$B어디 가는데 어디 가는데 어디 가는데?"
rows["112:825710267"]="오, 호드 ... 항상 개입하는 것 같네요. 환영은 정해진 것 같습니다.\010"
rows["112:830546121"]="이 초원자들에 비해 너무 강력해서, 케일레스와 그녀의 히포그리프들은 다른 무언가에 의해 쓰러졌어야 합니다."
rows["112:862560908"]="이 물건은 품질이 낮고 아마도 블랙마켓에 많은 가짜 유물 중 하나일 것입니다."
rows["112:872203541"]="내가 그들의 거짓 의식에 참여하지 않을거야 크로시크나 그의 고기에 특별한 것은 없다."
rows["112:884046856"]="이 표지판은 랜택 장교의 표지판입니다."
rows["112:894466767"]="이 고난을 살아남았기 때문에 다행이군."
rows["112:897813026"]="도와줘서 반가워요, 부인 수호자 전설적인 검을 찾을 수 있는 곳도 모르니?"
rows["112:902348208"]="내가 살던 곳인 다른홀드에서, 그 끝으로 일주일에 한 번씩 때려들었어요."
rows["112:910037565"]="이 곳에는 윤여적인 아름다움이 있지만 모든 나무와 식물에 있어서는 여전히 너무..."
rows["112:913956227"]="|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t 보너스 목표 시작: 시간이 끝나기 전에 모든 적을 물리치십시오!"
rows["112:931058457"]="이것은 단지 실버문 아타스가 우리 땅을 휩쓸고 나서 도시 대부분이 사라졌습니다."
rows["112:939139955"]="보름 폭탄 더 많이? 어제야 보름 폭탄을 없애고 있었던 것 같아요. 잠깐만요."
rows["112:939650493"]="당신 같은 사람이 주얼리 제작에 대해 더 많은 것을 배울 수 있게 도와주는 것이 축복입니다."
rows["112:947593726"]="카라반 내부에는 판매자 물품 상자와 함께 피오나와 그녀의 동료들의 개인 재물이 있습니다."
rows["112:97800410"]="소집이 완료되고 아즈하라의 군대가 전쟁에 모인 후, 티데헌터 네프톨론은 곧 쓰러질 것입니다."
rows["112:978833745"]="에라니쿠스, 꿈의 독재자는 엘루네의 빛에 의해 완전히 소비됩니다."
rows["112:979676686"]="좋은 꿈 의  ⁇  은 매우 강력 하다. 그 환상 들 에서 어떤 것 이든 명확 하게 하기 위해서는 집중 한 마음 을 필요로 한다!"
rows["112:982192492"]="네고라쉬를 물리치기 위해 이 구명 배를 사용했던 때를 조용히 기억해 보세요."
rows["113:1039498029"]="흠.. 참견하기 좋아하는 쇼가 아닐까 싶군. 내 나름대로 알아보지. 우선 가보게나. 곧 다시 연락하지."
rows["113:1054715279"]="내 갑옷을 고쳐라 코버스, 칼이  ⁇ 어졌어."
rows["113:1064813188"]="여기, 당신이 정복한 두려움의 본체입니다. 이제 적들의 마음에 공포를 불러일으키게 해 주십시오."
rows["113:108471298"]="숙소관 카우스는 당신의 필요를 충족시킬 수 있습니다."
rows["113:1086286728"]="토림, 나의 님이시여! 그대를 쓰러뜨릴 목적이 아니라면 왜 저들이 여기 왔겠습니까? 놈들을 막아야 합니다!"
rows["113:1102694383"]="트롤, 워시프, 당신의 군대가 당신의 명령을 기다리고 있습니다. 노스렌드 이 죽은자를 제거하기 위해!"
rows["113:1103621457"]="|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t %s는 캐스팅을 시작한다 |cFFFF0000|Hspell:124967|h[Draw Power]|h|r!"
rows["113:1104763709"]="이상한 건, 지난번엔 그 궤도 위치에 대해 언급한 것도 기억이 안 나"
rows["113:1139493054"]="슐로만스라는 이름으로 알려진 네크로만스학교는 서부 플라그랜드의 훼손된 케어 다로우 섬에 있습니다."
rows["113:1142757666"]=" ⁇ ! \"스몰츠!\" 왜 이런 삐걱거리는 거냐?"
rows["113:1153364664"]="용이 벼려낸 쿠엘세라는 칼도레이가 받았고, 그 쌍둥이 검인 쿠엘델라는 우리 종족이 받았다."
rows["113:1156190790"]="어르신 머스크파우는  ⁇ 에 딱딱하긴 하지만 항상 괜찮은 사람이었지"
rows["113:1162107175"]="만약 이게 함정이라면, 내가 눈치채지 않고 들어갈 수 없는 함정이야!"
rows["113:1167137256"]="여기 있는 내 친구에 대한 이야기와 우리가 함께 이룬 일을 들려주라고 상기시켜줘"
rows["113:1173016529"]="그 날을 볼 수 있을 줄 몰랐어요 다르나서스큰 고기를 들고 레오나 에어스윈드를 위해"
rows["113:1175932641"]="겁쟁이 같으니! 호드의 대족장을 그깟 돌멩이 몇 개로 막으려 드느냐? 진정한 정령의 힘을 보여주마!"
rows["113:1219970922"]="수년 동안 티탄의 전당에서 활보할 순간만을 꿈꿨는데, 티탄의 창조물 때문에 위험해질 줄이야..."
rows["113:1222400641"]="이쪽으로 가야만 없었어 화이트 파운을 찾아야 했지 아이언포지 지금쯤이면"
rows["113:1232361061"]="브랜, 이 손톱 좀 봐요."
rows["113:1234672316"]="그들은 땅을 파괴하고 만지는 모든 것을 파괴합니다. 그들의 비참한 독에 얼마나 많은 사람들이 목숨을 잃었습니까?"
rows["113:1241179981"]="자라잔에 대해 과소평가하지 마... 그는  ⁇ 고 강한 적이니까."
rows["113:1242173637"]="뭐, 좀 바쁘네요$B$B물론, 당신이 도와줄게라면, 전 이 세상에 모든 시간을 가지고 있습니다."
rows["113:1267611575"]="또 다른 주문을 내뱉어내세요. 정확히 같은 암묵적인 목표를 사용하지만, 다른 효과를 발휘합니다."
rows["113:1271174289"]="|TInterface\\Icons\\spell_nature_bloodlust.blp:20|t 어둠의 샤먼 이득 |cFFFF0000|Hspell:144302|h[Bloodlust]|h|r!"
