rows["113:1363765653"]="내가 바라는 것은 오직 그가 성스러운 빛의 정의를 깨닫고 열정을 다해 한때 아름다웠던 쿠엘탈라스를 재건하는 것뿐이라네."
rows["113:1373612681"]="정말인가, 무라딘? 네가 죽었다고 생각하며 지낸 지 수년 만에 다시 만났는데... 너를 다시 잃고 싶지 않다."
rows["113:1382924947"]="이 지점에서 북쪽으로 가는 첫 번째 전력으로"
