rows["113:1393946927"]="내 동생은 컨소시엄의 떠오르는 별입니다. 물론, 그는 인정하기에는 너무 겸손합니다."
rows["113:1422724526"]="알케미에 대한 능력은 아직 제 가르침을 충분히 활용할 수 없습니다."
rows["113:1438314907"]="정말 빚진 거니까 아빠랑 얘기해 틸러스 유니언에 들어가게 해"
rows["113:1443939216"]="이 기록은 불완전한데, \"내가 죽였어!\"라고 적혀있어요"
rows["113:1450958617"]="판다레인은 삶을 받아들이고 우리 주변에서 싸움이 많아서 우리가 무엇을 위해 싸우고 있는지 아는 것은 신나는 일입니다."
rows["113:1466891356"]="이 세상에서 제일 많이 사랑하는 토르타. 그렇게 오랫동안 떨어져 있다가 이제야 다시 만났구려. 마침내 우리 사랑이 다시 꽃필 수 있게 되었소."
rows["113:1467778335"]="이 모든 걸 살아남기 위해서는 새로운 친구가 필요해 오크들이 널 바로 죽이지 않길 바랄게요"
rows["113:1482847443"]="이게 우리가 마침내 토너먼트 우승을 위해 서로 경쟁할 수 있는 기회를 얻게 된다는 뜻인가요?"
rows["113:1483549932"]="아니, 아버지, 내가 해 줄게. $p 우리를 옹호하기 위해, 하지만 그들은 동의했습니다."
rows["113:1486702245"]="서부 달라란의 마녀 자매에서 반응제와 더 많은 것을 찾을 수 있습니다.$B$B무어헤드의 검은 고양이를 조심해"
