rows["113:1513204623"]="탈북자들이 잃어버린 포인트를 점령한 후 노스포인트 타워는 테라모어의 최대의 포항입니다."
rows["113:1520068636"]="안녕하십니까. 프라스 샤비 주인님께서는 출타 중이십니다. 샤비의 최고급 담배를 맛보시려면 내일 다시 와주시기 바랍니다! 삐빅!"
rows["113:1524643002"]="전쟁 구역으로 가요 사제들이 바깥 반지에 있어"
rows["113:1529205220"]="그때 애스리쿠스가 왔어. 그는 우리를 고통에서 구해주겠다고 했지. 그러곤 보호의 마법을 시전했어."
rows["113:1529323469"]=" ⁇  스톰스타우트를 들어본 적 없는데, 그 배는 빈 거 들었어요"
rows["113:1529714346"]="전기 충격은 환자의 생명적인 증상을 크게 증가시키는 데 사용될 수 있습니다. 하지만 우리는 이것을 자주 사용할 수 없습니다."
rows["113:1535473765"]="행운이 널 여기 데려왔다고 생각하지 마 운이 그랑 상관없어"
rows["113:1541226055"]="짜잔! 해냈어요! 이 엄청난 능력을 보세요! 소환의 대가, 윌프레드 피즐뱅입니다! 너는 이제 내 부하다, 악마야!"
rows["113:1542673207"]="키가 있는 게 뭐지, 죽여서 열쇠를 가져와 저 망할 구석에서 내보내줘"
rows["113:1565132282"]="네가 나를 불러왔을지도 몰라, 마녀야 하지만 그건 네가 내 이름을 바꾸지 못해"
rows["113:1575398978"]="얼라이언스는 수십 년 동안 우리를 반대했습니다! \010 우리 땅에 쌓은 탑으로 우리를 비웃고! \010"
rows["113:1579066167"]="일단 이 얼어붙은 땅덩어리로 만족하도록 하지... 덤벼라! 필멸의 생명체들아... 빠르고도 고통스러운 죽음을 맛보게 해주마."
rows["113:1581848156"]="다행히도, 고등 장로 들 은 더 이상 기초 훈련 을 하지 않아도 됩니다. 운동 하지 않을 때 나 는 더 행복 합니다."
rows["113:1610510226"]="나가와의 마지막 전투는 시작됐습니다."
rows["113:1644656265"]="당신과 당신의 동료들은 내 게스트입니다. 제가 당신을 위해 무엇을 할 수 있는지 알려주세요."
rows["113:1676676110"]="무엇보다도 우리는 자라잔에 그의 시간이 끝날 때로 돌아가게 될 것을 보여 주겠다"
rows["113:1680296712"]="|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t %s는 캐스팅을 시작한다 |cFFFF0000|Hspell:119360|h[Draw Power]|h|r!"
rows["113:1694818935"]="|TInterface\\Icons\\ability_warrior_bloodbath.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:117948|h[안니하일트]|h|r!"
rows["113:170167391"]="잃어버린 선다랄 영은 비닐한 물 앞에 조용히 무릎을 꿇고, 수영장의 조용한 표면을 바라보고 있습니다."
rows["113:1705457607"]="내가 안 보고 있을 때 뒤쪽으로 들어왔을 거야"
rows["113:1709618767"]="내 앞에 섰을 때, 그의 눈에 빛나던 긍지를 똑똑히 기억하네. 빛의 적들을 물리치겠다는 간절함과..."
rows["113:1719824880"]="항상 머리 보호를 입어라, 언제 미스 다라가 얼굴을 치는지 알 수 없어"
rows["113:1725033739"]="당신이 할 수 있는 일을 잘 해내면, 난 당신의 훈련을 계속할 수 있을 거야! "
rows["113:1751973822"]="돌아와서 정말 다행이다, 샤이. 제발 그렇게 엉뚱한 곳으로 가버리지 마라! 널 잃어버리면 네 부모님에게 어떻게 말하라는 거냐?"
rows["113:1757554042"]="아가마스, 첫 번째 문, 로헨도르, 두 번째 문은 이제 파괴되었습니다."
rows["113:1766008222"]="원자력들은 불쌍하다. 난 이 침해를 영원히 유지할 수 없을까 두려워한다. 더 많은 도움 없이는."
rows["113:1783835964"]="보시다시피, 배수자들은 곧 큰 군대를 沼地로 보내게 될 것 같네요."
rows["113:1803051646"]="마침내 자유가 됐어요, 감사합니다. 타헤트는 여기 없어요. 카이마스라는 잔인한 네퍼셋 군주도 데려갔어요."
rows["113:1807976288"]="여기 와서 살리한테 큰 포옹을 해봐, 찢어먹은 놈!"
rows["113:1821707735"]="영웅들은 눈치채기 좋은 곳이에요 볼진의 반란은 해안을 확보하지 못했어요"
rows["113:182527754"]="우린 너무 많은 희생을 했고, 우리의 싸움은 계속되고 있습니다."
rows["113:1839759978"]="매장에서 보이는 것 중 많은 것을 만들었어요. 어떻게 생각하시나요? 조심스럽게 대답하세요."
rows["113:1846533650"]="너와 상관없는 일에 사사건건 간섭해 왔겠다. 너는 이방인이자 침입자일 뿐이다. 죽을 준비나 해라!"
rows["113:1881798403"]="이 소녀는 아무것도 하지 않았으며, 앞으로 할 수도 있고 하지 않을 수도 있는 일에 대해 책임을 지지 않을 것입니다."
rows["113:1893515101"]="내 죽음은 아무것도 의미하지 않습니다. 다르나서스- 넌 더러운 놈이야 호드... 절대... 가질 수 없을거야!"
rows["113:1899114851"]="심지어 여기, 파도와 태양 사이에, 저는 이 땅에서 숨어있는 어둠을 느낄 수 있습니다.$B$B흥미롭죠?"
rows["113:1913183828"]="승리의 열쇠는 통제력이야 내 능력을 이용해 적의 마음을 지배하고"
rows["113:1925821436"]="오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 스피드 바르지, 오, 오, 오, 오, 오, 오, 스피드 바르치, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 스피드 바르치, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오, 오!"
rows["113:1926551483"]="이상한 배들을 볼 수 있어, 이건 모고선들이 아니다.$b$b침입자들은 누구야? 그들은 무엇을 원하는가?"
rows["113:1931425109"]="그럼 내가 내 세상에서 라흐리히와 싸워갈 때까지 저 여기 남겨두세요."
rows["113:1942062231"]="오그리마 경매집은 강함의 계곡에 있습니다. 부름스틱 수입 옆에 동쪽에 찾아보세요."
rows["113:1945582765"]="식물을 물을 주는데 도움이 됐어"
rows["113:1947501691"]="또 다른 배급이 올 때가 됐어요 광장에서 문제가 있다고 들었는데"
rows["113:1951256381"]="전쟁인도자님, 그러려면 요새의 지옥불정령을 모조리 동원해야 합니다. 자칫하면 역습을 당할 수가 있습니다."
rows["113:1982662517"]="내가 본 것들을 보고, 내가 한 것들을 하고, 여전히 숨을 쉬는 것은 행운의 괴물입니다."
rows["113:1998426091"]="이제 프리윈드 포스트가 있잖아, 그 멍청한 배만 남았어."
rows["113:1999750802"]=" ⁇ 은 놈이... 그놈이... 그놈의 큰... 이놈의 큰 멍청한 목을 봐!"
rows["113:2021104980"]="자라스, 즉시 검은 사원으로 돌아가라! 내가... 일리단 님의 명령서를 놓고 온 것 같다. 서둘러라!"
rows["113:2048704245"]="전 좀 준비할 게 있네요. 여러분은 시작하셔도 좋아요. 물 좀 만들어야 해서..."
rows["113:2049195947"]="챔피언, 환영합니다. 십자군 재판의 도전을 준비하기 위해 군대를 모았나요?"
rows["113:2058037913"]="그렇다면 그를 구해야 하오! 볼바르 폴드라곤을 구해내면, 얼라이언스와 호드의 갈등을 잠재울 수 있을 거요."
rows["113:2075313724"]="두 총알이 가슴에 있고 신발은 머리에 있습니다."
rows["113:2085382038"]="우리 모두 여기서 죽게 될거야!!!$B$B난 노예장관이야... 무역왕의 편을 잡기엔 너무 늦었는지 궁금하네"
rows["113:2106724557"]="난 그런 존경과 경의를 받을 자격이 없어, 드루이드 내가 내 종을 배신했어 이 땅의 병은 내 잘못이야"
rows["113:2108297571"]="좋아, 둘 다 놀러 가세요 그냥 마을에 머물러서 워그와 카라를 물가에 따라 쫓아내지 마세요"
rows["113:2117647428"]="<Vindicator Aesom>가 당신을 환영합니다.$B$B아드메티우스와 얘기했나?"
rows["113:2122560871"]="이 호드 이번엔 우리를 죽게 할 수 있는 빛 너무 늦기 전에 왕이 행동하기를..."
rows["113:2137156121"]="스파크터치한 사람들은 우리 중 최고의 전투자입니다. 늑대와의 싸움의 대부분을 수행합니다."
rows["113:2137292754"]="양의 극성을 가진 에너지가 음의 극성을 가진 에너지와 충돌하더라도 서로 극성이 상쇄되지는 않아요."
rows["113:2144892474"]="너한테는 약간의 기술이 있어 내가 내리는 몇 가지 것을 배울 수 있을 만큼"
rows["113:220448287"]="저는 아이언포지에 있었습니다.$B$B아빠가 내가 방에서 떠날 때 너무 보호가 되는 건 기이한 일이 아니죠 "
rows["113:221454434"]="뭐야! 이봐, 어서 물을 가져와라! 요새 전체로 번지기 전에 불을 꺼야 한다! 빨리, 젠장!"
rows["113:245424611"]="그게 다 해야 할 싸움이야, 여기서 나가서 첸과 리 리와 만나자"
rows["113:249003767"]="|cFF768EBD5년 전, 덤프민의 중심에...|r |TInterface\\QuestFrame\\UI-QUESTLOG-BOOKICON.BLP:32|t"
rows["113:250278495"]="주인님께서는 왕국을 살펴보고 모자라다고 생각하셨다. 그리고 자비도 주저함도 없이 심판하셨지. 모두 죽여주마!"
rows["113:255318136"]="당신같은 사람들이 우러다니는 냄새가 난다."
rows["113:262674028"]="우리는 이 계곡의 물의 독특한 특성들이 그 지역의 풍요로움을 주게 된 주된 이유라고 생각합니다."
rows["113:272620807"]="우리의 복합폭탄은 탄도함 상기의 방패를 파괴했습니다."
rows["113:273778741"]="손 들어봐, 그린킨스, 내 사람들은 새로운 지형을 줄거야."
rows["113:293134684"]="하지만, 네 눈을 보고 네 맥박을 들으니 알겠구나. 너는 내가 약속한 영생을 뿌리치고 날 파괴할 작정임을 말이다!"
rows["113:312282888"]="\"오픈 상처로 덮여 있는 거대한 검은 드래크는 악의의 눈으로 당신을 쳐다보고 눈 깜빡이지 않는다\"."
rows["113:336031316"]="썬더머, 우리가 성지 위를 떠나면 난 널 이렇게 강하게 부딪힐 거야 네 신발이 유일한 존재가 될거야!"
rows["113:368834872"]="내 도전은, 당신이 그것을 받아들이면, 당신의 도련과 발의 일을 시험할 것입니다 심지어 생명을 위협하는 위험에 한가운데."
rows["113:376853217"]="요고는 우리와 다른 부족의 사람입니다. 그는 북쪽에서 멀리 왔고, 그를 이리로 데려온 것에 대해 거의 말하지 않을 것입니다."
rows["113:39696821"]="마법의 진동이 멈추자 그의 숨겨진 목적이 밝혀졌어. 우린 함정에 빠졌고 그는 천천히 우리의 힘을 빼앗아갔어."
rows["113:422291278"]="주인은 지옥의 불을 비우리라 아제로스그리고 마침내 청소를 할 것입니다 빛 이 불행한 세상으로부터!"
rows["113:435825404"]="잘했어, 그 짐승들과 싸웠어, 참 멋졌어!"
rows["113:438206806"]="근처에서 발견된 원동물과 불 거대?"
rows["113:446350138"]="폭발보다 더 좋은 것은 무엇일까요? 많은 폭발이 있습니다. 이 모퉁이에 우리는 빅 바다 붐을 가지고 있습니다!!"
rows["113:48279305"]="어둠의 여왕이여, 나와 함께합시다! 이곳을 되찾고자 힘들게 싸우는 동안 너무나 많은 피가 흘렀소. 왕실은 그대의 것이오!"
rows["113:485165951"]="좋은 툴라스는 귀족 여성이며, 빛의 강렬한 수호자입니다. 그녀의 수업은 숙소에서 가르칩니다."
rows["113:488379787"]="우리는 이 구멍을 봉쇄하기 위해 왔어요 아제로스- 세계 기둥이 이쪽 구멍을 수리할 필요가 있어요"
rows["113:523405367"]="솔직히 말하지... 네 녀석들이 나타나리라 어느 정도 예상하고 있었다. 이곳이 마음에 들길 바란다. 너희가 영원히 잠들 곳이니..."
rows["113:529501451"]="새와 오래된 적들이 이 섬을 휩쓸고 있습니다."
rows["113:535976448"]="둘 다 얼라이언스 그리고 호드 항구로 가는 배가 있고, 대전 포항에 대한 공격이 진행될 겁니다."
rows["113:541754332"]="|TInterface\\Icons\\spell_shaman_lavasurge.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:98710|h[Sulfuras Smash]|h|r!"
rows["113:568914739"]=" ⁇ 드프레이 마을의 울란은 \"전문 요리책\"을 팔 수 있어"
rows["113:585739905"]="...내가 직접 봤어 Mogu 군대가 강원도를 공격하고 있습니다."
rows["113:592320625"]="달철에 처음 일한 지 몇 년이나 됐지만 기법을 잊지 않았어"
rows["113:595800291"]="정말 리치 왕의 대리인이 이 한심하기 짝이 없는 마상시합장에서 무릎 꿇었다고 생각했나?"
rows["113:616125855"]="은행은 오그리마번으로 갈거야 북쪽으로 가서 그 놈들 중 한 명에게 얘기해"
rows["113:618601385"]="피는 생명이고, 피의 흐름이 통제될 수 있는 것처럼, 우리의 적들의 생명도 통제할 수 있습니다."
rows["113:622152869"]="시험을 완료하기 위해 10의 불 댄스 스택이 있을 때까지 룬 안에 남아서 화재에 빠지지 마십시오."
rows["113:63000559"]="이하갈루크에 변화가 일어나고 있습니다. 사우로크는 서로 반란을 일으키고 있습니다."
rows["113:630637678"]="그 단어를 읽을 수는 없지만 마법은 더 이상 존재하지 않는 세계를 가리키고 있습니다."
rows["113:669157262"]="샤를 감시하고 감옥에 가둬야 하는 우리의 신성한 의무입니다."
rows["113:687252142"]="이 돼지는 육식에도 좋지 않고 먹기에도 좋지 않으며, 전투에도 적합하지 않습니다."
rows["113:710951330"]="내가 너무 오래 내 형제를 참았어. 이제 모든 것을 바로잡고 그를 죽이는 시간이다."
rows["113:717977104"]="바리마트라스? 아니, 그는 몇 년 동안 보고하지 않았습니다. 그는 여왕에게 중요한 일에서 떠났다는 것은 의심의 여지가 없습니다."
rows["113:738880111"]="우리에겐 너무 늦었어, 살아 있는 사람."
rows["113:754002416"]="그런데 어째서 위험에 빠지게 된 거지? 그는 그저 부족의 골칫거리인 정령을 지배할 힘을 얻으려 한 것뿐이라네."
rows["113:76307496"]="로어워커가 죽으면 우리 중 많은 사람들이 헛되이 죽었을 겁니다\010처형을 막기 위해 나와 함께 하시겠습니까?"
rows["113:770128808"]="지구 태블릿을 지키는데 도움이 돼야 해 Twilight Hammer은 태블릿을 안 취하기 전 멈추지 않을 거야"
rows["113:770834152"]="안녕, 낯선 사람, 지역 주민들에게 꽤나 좋은 인상을 남기고 있어"
rows["113:772957394"]="이렇게 빨리 가려고?$b$b작은 수수료로 수도권으로 이동할 수 있어요$b$b떠나고 싶다고 확신이 있나?"
rows["113:779470128"]="그가 뿔피리를 손에 얻자 무서운 적이 그를 추격하기 시작했는데... 기억이 나질 않는군... 그다음에... 무슨 일이 일어났는지 말이야."
rows["113:803033266"]="저주를 포기하지 마라, 너흰 한때 길네아스의 남자와 여자였어"
rows["113:803747370"]="이 인종들을 전쟁에 참여시키고, 이 땅을 전쟁의 공포로 훼손시키려?$b$b정말 원하는 건 그게냐?"
rows["113:809175563"]="스톰윈드에서 오기로 한 제2 대대는 아직 아무 소식도 없고, 북동 지역에서 잿빛가죽 일족의 움직임이 보고되고 있으니..."
rows["113:827721639"]="진주 마을의 중심은 깨끗했어요."
rows["113:830045792"]=" ⁇ 드리스 윈드웨이버의 시신이 여기 펼쳐져 있습니다.  Twilight's Hammer의 기의의 피해자인 것 같습니다."
rows["113:832054908"]="내가 알 수 있는 대로, 이 싸움에는 어떤 편도 없었어. 왜 야롱들은 서로 자유로울 때 죽였을까?"
rows["113:833397350"]="모고들도 아이였어 타이탄들의 자식이었는데"
rows["113:860399277"]="고엘, 그만둬야 돼 네 분노는 옳고 그름이지만 널 잡아먹을 거야"
rows["113:866561046"]="마침내 이 순간이 이루어졌습니다. 나의 죽음은 끝났습니다."
rows["113:867221558"]="가드게츠안의 디르지 퀴클레브는 요리 예술의 마스터입니다. 자신을 개선하려면 그를 찾아야합니다."
rows["113:904009846"]="썬더 킹의 궁전은 앞쪽에 있어 그의 요새를 공격하기 전에 섬에 발걸음을 잡아야 합니다."
rows["113:914525989"]="샤도파인은 수백 년 동안 이 벽을 지키고 있지만, 자존심 때문에 외부의 도움을 거절하지 않을 것입니다."
rows["113:946349933"]="이제 당신의 골격은 영원토록 노력할거야... 기다려야... 침입자? 여기!"
rows["113:946805789"]="아주 좋은 일이에요, 우리의 방어는 최소한의 희생으로 유지되었습니다."
rows["113:949776739"]="이 나무는 희망의 상징입니다. 시간이 지남에 따라 그 땅이 치유되고"
rows["113:953665022"]="달의 축제는 우리 드워프들에게 특별한 시간이지요. 축제 기간 동안 선대의 장로들에게 찾아가서 존경을 표시한답니다."
rows["113:959068454"]="다 잔다라리 씨는 막아야 합니다. 아제로스 그들의 명령에 따라, Dee는 우리 모두에게 위협이 될 것입니다."
rows["113:966779270"]="난 이제 네가 가진 전부야, 그래서 뭔가 원하면 빨리 해"
