rows["114:231296782"]="이건 아무래도 쿠에가 중요하게 생각할 것 같은데... 이런 것에 대해서는 쿠에가 잘 알죠. 전문가는 아니지만 아는 게 많다고요."
rows["114:26748557"]="영원노래 숲 말입니다, 달포르스 님. 저는 아서스가 죽음의 낫을 휘두르기 전에 영원노래 숲이 얼마나 아름다웠는지를 생각하고 있습니다..."
