rows["114:288816948"]="고단의 루네워크는 당신이 갈 곳이고, 그래그의 서쪽 끝에 있는 지혜의 계곡 옆에 있는 곳이죠."
rows["114:31636604"]="반려동물의 재능을 모두 지워버릴 수 있어$b$b할 때마다 더 비싸게 되죠."
