rows["114:408523063"]="당신이 앉기 전에, Myang 선생님이 가장 실용적인 전투 기술을 가르쳐 줄 것입니다."
rows["114:414503905"]="반갑다, 신병 제군들. 난 훈련교관 바둠이다. 제군들은 앞으로 며칠간 교육을 받게 된다."
rows["114:417503718"]="콜라크가 왔노라, 나약한 존재들이여! 눈사태 무덤은 겨울도끼 부족의 것이다! 아, 그게 아니라... 고뇌의 투기장은 겨울도끼 부족 거다!"
rows["114:418304945"]="절대 그런 것은 아니오! 내 양심을 걸고 말하겠소. 우리 일족의 무절제는 우리 자신과, 그동안 힘들게 쌓아올린 모든 것을 파괴할 거요."
rows["114:423937306"]="(상가  ⁇  진 수에 대해 이야기하고, 어떻게 그와 얘기할 것인지, 그리고 그의 지팡이를 심어주고 지나가는)"
rows["114:425071050"]="으아아! 아직... 기뻐하긴 이르지... 승리는 잠깐일 뿐! 상상조차 할 수 없는 강력한 존재로 돌아오겠다!"
rows["114:428573251"]="가로쉬의 요청으로 내 사람들을 데려왔는데 우리가 게임에서 보인처럼 희생될 것이라는 걸 몰랐어요"
rows["114:440948752"]="아니, 아니, 난 당신 사람들을 배신하려는 생각은 없었어요."
rows["114:441555496"]="|TInterface\\Icons\\inv_stave_2h_deathwingraiddw_d_01.blp:20|t%s 앞으로 떨어지면, |cFF04FC32이세라의|r 플랫폼!"
rows["114:471455716"]="만약 맨티드의 전력이 오면, 우리는 그들을 안전하게 붙잡을 수 있을 겁니다."
rows["114:492026020"]="왜 안 돼? 다른 일에 바쁘니? 그 작은 괴짜 리베트는 당신을 위해 뭔가를 부탁했나?"
rows["114:505060900"]="|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t맹인 용은 뒤로 물러서 던진다 |cFFFF0000불꽃이 타오르는 것!|r"
rows["114:512347095"]="제 임무는 거의 완료됐습니다. 오셔서 이국적 새들을 보러 가세요."
rows["114:515960959"]="로xxik이 훨씬 더 잘 할 수 있어 오그리마에서 찾을 수 있어"
rows["114:534099943"]="니라 간호사는 도시 남동쪽 끝에 있는 갈로우스 엔드 타버너에 들어오는 모든 미래의 고객을 환영합니다."
rows["114:535496649"]="|TInterface\\Icons\\ability_parry.blp:20|t 마스터 스노우드리프는 그의 |cFFFF0000|Hspell:106454|h[파리 입장은]|h|r를 가능하게합니다!"
rows["114:540576625"]="|TInterface\\Icons\\spell_fire_felrainoffire.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:88972|h[Fel Firestorm]|h|r!"
rows["114:548474920"]="|TInterface\\Icons\\spell_holiday_tow_spicecloud.blp:20|t 알리스라저의 불 |cFFFF0000|Hspell:99432|h[Burns Out]|h|r!"
rows["114:549551967"]="그는 마블스트롬으로 향하고 있습니다. 우리는 그를 막아야 합니다, 그가 Deepholm에 탈출하면 우리는 결코 다른 기회를 얻을 수 없습니다."
rows["114:550975677"]="스터미파이크 스터빌은 당신들의 도움을 요청합니다."
rows["114:554581751"]="콜이 맛있는 요리법을 듣는 걸 좋아해요."
rows["114:563217010"]="대체 포위 차량이 곧바로 당신 문 앞에 도착해"
rows["114:563333249"]="내가 패했어, 넌 내 잘못을 보여줬어."
rows["114:580256184"]="당신은 왈프가 언급한 재능 있는 사냥꾼이어야 합니다. 왕의 관심을 끌 수 있었던 사냥꾼이죠."
rows["114:596045664"]="싫어! 가지 마! 오빠는 나라를 위해 싸운다지만, 누가 인정해 줄 것 같아? 여기 보낸 건 죽으라는 소리라고!"
rows["114:600214606"]="어서 오게, 용사여. 오늘, 여러 지도자와 동료 앞에서 자신이 얼마나 가치 있는 투사인지 증명할 수 있을 걸세."
rows["114:603113848"]="여러분들의 도움에 감사드립니다. 전사한 자들을 돌볼게요 아이언포지."
rows["114:61930429"]="비행선이 추락하면서 우리는 비상 탈출 장치를 가동했습니다. 그게 제 마지막 기억이죠. 가서 도울 일이 있는지 봐야겠군요. 감사합니다!"
rows["114:655299004"]="아이언포지 은행 앞에는 대부인 윈터가 있습니다."
rows["114:677130553"]="자기 사업을 운영하는 것만큼 좋은 건 없어요. 하지만 내가 모든 걸 직접 해야 할까요?"
rows["114:700851328"]="내가 여기 바쁘다는 걸 알 수 없지? 북쪽으로 가서 오그리마로 가서 그 곳의 한 분에게 물어봐."
rows["114:704606508"]="안녕, 친구, 여기 방문객이 많지 않소."
rows["114:706615412"]="다크스피어와 그녀의 동맹들은 공격할 것입니다 오그리마 육지에서 해를 통해 공격할 수 있게 해"
rows["114:72856922"]="조갈 같은 멍청이한테 이렇게 신성한 일을 맡기는 건 바보였어"
rows["114:757257938"]="크롤미르로군... 요쿰, 고맙도다. 이 망치가 아직도 남아 있으리라 감히 기대하지 않았다. 다시 한번 영광스러운 전투에 나서게 되리라!"
rows["114:759172186"]="개처럼 착륙할 수 밖에 없어 곧 이 모든 놀라운 짐승들이 주인에게 지배될 거야"
rows["114:7734502"]="난  ⁇ 을 과장해서  ⁇ 에 대해 아주 효과적이지만, 한 번만 사용할 수 있어요!"
rows["114:780970121"]="이 방들을 계속 유지하기 위해 할 수 있는 모든 것 이 있습니다."
rows["114:789880254"]="자네가 우리를 또다시 어둠의 길로 끌고 가도록 내버려두진 않겠네, 젊은 헬스크림. 그런 날이 오면 내 손으로 자네를 처치해 주겠네..."
rows["114:801273225"]="주변을 잘 지켜봐요 제가 가는 길은 발가르데로 돌아갈 때 같은 길이죠"
rows["114:81451712"]="|TInterface\\Icons\\spell_holy_innerfire.blp:20|t Glubtok은 움직이는 |cFFFF0000|Hspell:91398|h[Fire Wall]|h|r!"
rows["114:824927759"]="- 안보군, 안보군, 네 선물과 저주야"
rows["114:84656361"]="시민, 당신은 강대한 놈처럼 보이는데, 우리 경비원들이 좀 얇게 여기 흩어져 있어"
rows["114:866373474"]="우린 적대적인 영토로 들어갑니다 얼라이언스 지휘자 순서."
rows["114:878977320"]="그는 전투 코도 부부가 만났어요.$b똑똑하긴 하지만 늑대는 한쪽이 다른 쪽을 이길 때까지 기다렸어"
rows["114:880438772"]="수백 명의 젊은 전사들을 훈련시켰는데, 워크시프는 무분별하게 피를 흘리고"
rows["114:883214430"]="머리가 없는 말자는 스카르렛 수도원에서 살고 가끔씩 어른들을 겁에 질려나서 나만 겁에 질리지 않아요"
rows["114:893496217"]="대체 무슨 근거로 박쥐가 저 각도로 안전히 착지할 거로 생각하는 건지 모르겠단 말이야. 남는 건 부러진 목에 냄새 나는 박쥐 스튜밖에 없을 거라고."
rows["114:8977801"]="머리가 없는 승마자는 이제 쫓겨났어 잠시 쉬어 숨을 쉬지만 항상 깨어 있어야 합니다."
rows["114:905660678"]="나 는 잎 을 길 에서 깨끗 하게 하고 싶어 합니다. 너무 많은 잎은 스프리트를 가져옵니다. 성전 수도사들은 스프리트를 좋아하지 않습니다."
rows["114:936721021"]="비행기를 \"시즌\"하기 위해서는 몇 번의 좋은 충돌이 필요합니다.$B$B정신이  ⁇ 은 괴물은 순수한 비행기를 날지 않습니다."
rows["114:944779396"]="마이너스 스님은 Twilight 지도자들과 만나고 있어"
rows["114:947788099"]="다 됐습니다! 이제 문이 열렸습니다. 이 너머에 있는 것들을 물리치길 바랍니다. 난 즉시 키린 토로 돌아가 보고해야겠습니다."
rows["114:952032627"]="그래도 계속 애써 주세요. 우리 짐작대로 이게 순간이동기라면, 공격에 대단히 유용할 겁니다."
rows["114:953726258"]="그는 전투가 시작되기 전에 유적들을 탐구하는데 성공했고 예언이 새겨진 루닉 판자 세 개를 발견했습니다."
rows["114:966687972"]="이 분쟁은 인종 전쟁 뿐 아니라 그들의 증오가 이 땅을 포식 할 것 이다 - 우리는 여기에 참여 하지 않을 것이다!"
rows["114:973056497"]="아웃랜드에서 위대한 전쟁이 벌어지고 있다고 들었는데,"
rows["114:97410793"]="이 돌의 트로그는 크림슨 영역의 성장에 있습니다.$B$B이 곳에는 이상한 힘이 느껴지고 있어 조심해"
rows["114:979468742"]="오늘 내가 본 중 가장 슬픈 군인들 중 한 명이 되실 겁니다."
rows["114:984269404"]="저 젠장, 존니, 여기 다 블랙록스, 한 개의 타워가 있고 두 개의 작은 호박이 있어\010"
rows["114:984406686"]="코르가 스트롱마네, 한때 포로였던 얼라이언스, 지금은 자유롭고 무장 없는 타우렌."
rows["115:1026166170"]="다크문 페어는 지금 아웃랜드에 있는 테로카르 숲에서, 샤트라스 시티의 남쪽에 위치하고 있습니다. 놓치지 마세요!"
rows["115:1041502559"]="세탁물과 물 덩어리 좀 봐요, 다음엔 내가 필요한 걸 불러서 욕조에 넣어요"
rows["115:1054406647"]="건방진 놈들. 네 놈들은 잠시 시간을 늦췄을 뿐 결코 너희의 운명을 피할 수는 없다. 하나가 쓰러지면 열이 새로 일어날 것이니... 그것이 나 카자크의 뜻이니라..."
rows["115:1072247338"]="여러분의 안전을 위해, 저는 피요드의 다른 지역으로 단편 비행을 허용할 수 있습니다."
rows["115:1080853827"]="라이트, 자네가 만든다던 새 혼합물은 다 만들었나? 가게에 포자가 잔뜩 널려 있는 꼴은 그만 보고 싶단 말일세!"
rows["115:1116330440"]="그림자 사냥꾼 덴하이는 이 게시판을 이용해 중요한 발표와 보너스 소식을 Zabra'jin의 적에 게재합니다."
rows["115:1119140798"]="난 여긴 진주족에 대해 자주 궁금해 하지만 그들은 어업하는 법을 알고 우리보다 더 잘"
rows["115:1122766091"]="하지만 이제 물건이 있어 로가나어가 말한 힘을 느낄 수 있어"
rows["115:114729908"]="고레도미가 깨어있는 때마다 응원해"
rows["115:1153977888"]="그놈을 묶어서 저한테 맡겨라 내가 빨리 처리해줄게"
rows["115:1177509047"]="책과 스크롤의 덩어리를 통해 총을 발사하여, %s은 특히 관심을 가지고 하나를 살펴보기 시작합니다."
rows["115:1178533184"]="이 넓은 지역 곳곳에는 조상님들의 뼈가 잠들어 있습니다. 그 영혼은 승천해서 위상의 방에 거하지요."
rows["115:1185078260"]="고엘의 정신은 너무 불안해져 빨리 움직이지 않으면 스스로 붕괴될 수 있습니다"
rows["115:1188439217"]="|TInterface\\Icons\\ability_warrior_shieldmastery.blp:20|t%s 캐스트 |cFFFF0000|Hspell:117961|h[무비한 방패]|h|r!"
rows["115:1190788224"]="넌 야생이 됐을지도 모르지만, 길니안 피가 네 혈관을  ⁇ 어 호드!"
rows["115:1191198162"]="내 운명에서 숨은 게 너무 오래 됐어 내가 해야 할 일은 더 명확해졌어$B$B로켄은 내 손으로 파괴되어야 합니다."
rows["115:1195755023"]="|TInterface\\Icons\\ability_warrior_bloodnova.blp:20|t %s은 부상당하고 자란 |cFFFE9A2E Blistering Tentacles|r!"
rows["115:1196756360"]="전 세계 최고의 보석에 꽂힌 팬더를 원해요"
rows["115:1213078628"]="|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:143309|h[Swirl]|h|r!"
rows["115:1230668494"]="지금에도 항공기가 다가오고 있습니다. 그 미묘한 용량은 테라모어 섬과 여전히 거기에 있는 모든 사람들을 납작하게 될 것입니다."
rows["115:1239901391"]="기초를 배우기 전까지는 제 기술을 공부할 수 없습니다. 훈련에 관심이 있다면 카마리와 이야기하세요."
rows["115:1243110122"]="누구도 살아있는 불꽃을 꺾을 수는 없다! 나타나라! 불의 신하들이여! 나오너라! 증오의 피조물들이여! 네 주인이 부르노라!"
rows["115:124758495"]="배들이 야만 동물들에 의해 불타진 것을 보고 우리의 마음은 무너져 내렸어요"
rows["115:1256152584"]="메라에게 돌아가게. 돌아가서 내가 용서한다고 전해주게나. 그리고 그가 왜 그러는지 이해한다고도 전해 주게."
rows["115:1266754864"]="잘했어 군인 몇 개 더 더하면 우리 기둥이 전투에 올라갈 수 있는 말들로 가득차게 될 거야"
rows["115:1271849251"]="드래곤의 여왕, 어떻게든 내 영웅적 열쇠를 놓쳤어"
rows["115:1287182698"]="다음에 소개할 이분은 성스러운 빛을 섬기는 데 둘째 가라면 서러울 인물입니다! 여러분, 은빛 고해사제 페일트리스입니다!"
rows["115:1299288341"]="아제로스와 드레노어에 있는 거대한 수로의 무질서한 본성은 물의 정령들이 받은 고통이 직접적으로 나타난 결과입니다."
rows["115:1303355597"]="- 확실해?$B$B내가 당신의 마음에서 배운 재능에 대한 지식을 지워버린 후에는 돌이킬 수 없습니다."
rows["115:1310970376"]="마우티의 눈을 봤어? 데이가 밝게 빛나고 있었다."
rows["115:1325498703"]="라이트의 희망 사당은 플라그랜드에서 요새로 남아 있습니다. 아르헨트 Dawn의 발걸음은 그 지역을 확보하는 열쇠입니다."
rows["115:1329424495"]="헤르메시우스 빨리 오세요! 얼라이언스 탐험."
rows["115:1332358420"]="다크스피어가 떠난 시기를 말해줄 수 있어? 오그리마난 가로쉬의 행동을 직접 봐야겠어"
rows["115:1340788771"]="하! 오히려 자네의 구멍 난 고물 전차가 폭발을 일으켜 내가 파편에 맞지나 않을까 걱정일세!"
rows["115:1345789081"]="당신 같은 학생들이 많으면 좋겠어요. 적의 영역으로 진출하는 사람은 많지 않을 겁니다."
rows["115:1348289020"]="시간이 됐군! 어서 목재를 챙겨서 이동하라고. 아무리 호드라도 세상 끝날 때까지 싸우진 않을 거란 말이지. 돈을 벌 때는 바로 지금이라고!"
rows["115:1360034043"]="불 축제 때 원자불은 듀로타보다 더 뜨겁게 타는 것 이다. 얼라이언스 는 그것을 주장 할 수 없습니다!"
rows["115:1367790328"]="하지만 여러분은 혼자가 아니오. 내 부하들이 여러분에게 가장 필요한 보급품을 짐노새에 실어 가져왔소."
rows["115:1369271318"]="물은 어디에 있죠, 엠마? 물 가져왔어요, 엠마? 내가 아니었다면 저 작자는 물이 어떻게 생겼는지도 몰랐을 테지, 암."
rows["115:1373994350"]="타란 주가 아버지처럼 샤도파인을 이끌고 있지만 그는 우리 수도원 문을 닫기로 결정했습니다."
rows["115:1374533174"]="프로스트울프 리lief Hut은 프로스트울프 킵에 위치하고 있으며, 프로스트울프 타워의 남쪽에 있습니다.$B$B현재 어느 쪽도 통제하지 않습니다."
rows["115:1381626083"]="|TInterface\\Icons\\spell_fire_meteorstorm.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:105651|h[Elementium Bolt]|h|r!"
rows["115:1398599912"]="우리는 천개늘의 생존자들을 위해 뉴 타라나어에서 구호를 진행하고 있습니다."
rows["115:1405004970"]="방해에 대해 진심으로 사과하지만, 여러분께 관심이 있을 만한 것이 있습니다."
rows["115:1420058701"]="가로쉬의 착륙과 팔레아는 안개로 지워졌어요"
rows["115:1423353821"]="여기 있어 반갑습니다. 네 바람의 계곡에서 노력한 지 얼마 되지 않았습니다."
rows["115:1431913439"]="우리의 새로운 동맹들은 우리를 다시 옛 영광으로 되돌려 주게 될 것입니다."
rows["115:1454563750"]="내가 두려워할 건 아니지, 이 반종이 내 황제일 수 없어!"
rows["115:1469696190"]="이제 우리의 일은 끝났고, 우리는 승리의 소식을 클라시키 협의회에게 전달하자."
rows["115:1471050043"]="쿠엘델라를 만든 이에게 돌려주고자 여기로 가져온 것이 바로 나였다. 이 검을 깨뜨리면서, 그 힘도 깨뜨렸지."
rows["115:1475636047"]="글쎄요, 이미 말한 대로 발사 준비를 끝내려면 시간이 좀 걸릴 것 같습니다. 다시 알려드리지요."
rows["115:1476136714"]="천 수도원에서 에너지를 집중시키는 방법을 배웠는데, 작은 손가락으로만  ⁇ 을 터치할 수 있었습니다."
rows["115:1479488022"]=" ⁇ 프 드레이크 능력을 발휘해\010|TInterface\\Icons\\ability_vehicle_launchplayer.blp:64|t"
rows["115:149022232"]="이 자리에서 약속한다, 형제자매여. 리치 왕은 패배할 것이다! 오늘 여기서, 나는 연합을 선언한다."
rows["115:1491527013"]="당신은 당신의 도시를 통해 호드의 분노를 볼 것입니다! 당신은 두 개의 당신의 왕좌를 갈라 볼 것입니다! 나는 맹세!!!"
rows["115:1495900105"]="이 조각은 \"야샤르지의 날개병\"에 대해 이야기합니다."
rows["115:1503059911"]="내일은 없던 것처럼 구매해봐요 얼마나 오래 걸릴지 누가 알죠?"
rows["115:1504533066"]="내가 왜 목마른에 있는지?"
rows["115:1534724093"]="함께하시지요, 아버지. 저와 손을 잡고 함께 이 세계를 스컬지의 이름으로 궤멸합시다. 리치 왕의 영광을 위하여!"
rows["115:1550516477"]="제 옷은 그녀가 내한테 부과하는 모든 것과 완벽하게 잘 어울리길 바랍니다."
rows["115:156789072"]="오늘날 우리 의 우정은 얼라이언스 과 확고 한 상태 입니다! 오늘, 우리 는 형제 자매 로 나갑니다. 우리 의 새 미래 를 향해!"
rows["115:1580758620"]="잉바르는 드래곤 라이더들을 보내서 곤충에 대항해 내려가게 됩니다."
rows["115:1591201430"]="금수중 하나에 빠져있던 중, 그들이 저를 잡았어요."
rows["115:1596097172"]="|cFFFF0000|Hspell:135096|h[음파가 터져]|h|r 충돌 지점에서 벗어나서 피해를 줄일 수 있습니다"
rows["115:1605487973"]="피곤한 여행자여, 내 해변으로 데려온 물을 축복해줘"
rows["115:1618703400"]="그림자 춤의 비밀은 통제입니다.$B$B정확성$B$B민첩성.$B$B그레이스$B$B너무 많은 움직임도 없고, 너무 적은 움직임도 없습니다."
rows["115:1624381077"]="이 입수유는 거의 가혹한 향을 가지고 있습니다.$b$b(사나리오에서는 425 이상의 아이템 레벨을 요구한다.)"
rows["115:16369471"]="여기 온주간 있고, 먼 땅으로 가자"
rows["115:1666523081"]="알시아 님, 묘지에서 이상한 일들이 일어나고 있다는 보고가 들어왔습니다. 시장께서는 어둠골에 대한 공격의 전조라 믿고 계십니다."
rows["115:1695412236"]="우리는 많은 물품을 가지고 있지만, 우리는 여전히 많은 것을 필요로 합니다."
rows["115:1700316553"]="나아루의 좌석을 둘러싼 그림들을 찾아다니며 디야를 찾는데"
rows["115:1727121551"]="우리는 판다렌이 아니라 조상들을 숭배하지만 그들의 기억과 그들이 우리에게 전해 준 지혜를 존중합니다."
rows["115:1752247096"]="우리들은 해상에서 있는 비공개 해적들에 의해 봉쇄당하고 있어요!$B$B도와줄 수 있을 거 같아?"
rows["115:1759080398"]="고아 모녀는 드루이드들이 새, 고양이, 곰으로 변할 수 있다고 하지만 당신은 모두 조합처럼 보입니다!"
rows["115:1763708466"]="생각할 것도 없습니다. 공격해야 합니다. 우리가 불리하다는 건 알지만, 타운카로서 가만히 앉아 당할 수만은 없습니다."
rows["115:1764873598"]="이건 아무래도 쿠에가 중요하게 생각할 것 같은데... 이런 것에 대해서는 쿠에가 잘 알죠. 전문가는 아니지만 아는 게 많다고요."
rows["115:1776319097"]="내 경호들의 목숨을 구해줬어 영웅, 내 영원한 감사가 있어 이제 우리의 임무를 계속할 수 있어"
rows["115:1778494554"]="네퍼셋 반란군과의 전쟁에 대해 고의회의 각 구성원이 결정한 적이 있습니까?"
rows["115:1781357178"]="내 나이만큼 살면 사랑 잊기 쉽지만 기억이 나가는 게 좋다"
rows["115:1796219695"]="보아라, 잠잠한 타이탄 힘, 내 자신의 드래코닉 본질에 휩싸여, 파다레네 천상의 지혜로 온화되어"
rows["115:1799710031"]="피쉬의 친구니까 동물에 대한 지식이 있어 농장에서 많은 도움을 줄 수 있을 거야"
rows["115:179995085"]="마법봉의 모양은 단순해요. 다르톨은 이 마법봉을 만들 때 그의 신비한 지식을 사용하지 않았거든요. 성격상 드루이드의 것에 더 가깝죠."
rows["115:1805608873"]="그럼 역사에 대한 당신의 지식을 시험해 보겠습니다. 이 중 누가 바리안 린 왕의 첫 아내에게 올바른 이름인가?"
rows["115:1826131559"]="이 태블릿에 있는 표시는 고대 다이어그램과 강력한 단어들을 보여 주는데,"
rows["115:1872578624"]="이런 때야 우리가 가장 친한 친구인 걸 기억해요"
rows["115:1886381898"]="왕 바리안 류린의 명령으로 은버브룩 주민들에게 제안을 할 권한이 있습니다."
rows["115:1886583323"]="켈트후자드의 통치 후에도, 리치 왕년 말 이후에도, 형제자매는 계속 살아가고 있습니다."
rows["115:1894821482"]="귀여운데, 내가 널 때릴 수 있다고 생각하면 지금 당장  ⁇ 을 거야"
rows["115:1897304081"]="마그니의  ⁇ 에 의해, 그는 판자를 읽을 때 사용했던 루닉 키를 재구성해야 합니다. 우리는 그의 발자국 바로 뒤에있을 수 있습니다!"
rows["115:1907625343"]="네싱웨리는 뛰어난 사냥꾼이지만, 우리에게 적절한 동물 사냥 전술을 가르쳐 줄 수 있는 드루이드가 있었으면 좋겠어요."
rows["115:1933358485"]="다라란에는 많은 우편 상자가 있습니다. 많은 구석에서, 거의 모든 숙소와 은행 밖에서, 심지어 크라스스 상륙도 있습니다."
rows["115:1972130981"]="맞아, 이트리그 시간대가 좋지 않아 최고의 대사가 지옥으로 보내지도록 해"
rows["115:1974584667"]="에버송에서 나오는 신선한 공기가 가끔 내 위를 짜증나게 해"
rows["115:1981336047"]="돌아와서 정말 다행이다, 샤이. 제발 그렇게 엉뚱한 곳으로 가버리지 마라! 널 잃어버리면 네 부모님에게 어떻게 말하라는 거냐?"
rows["115:1996899270"]="축복받은 조상님들이여! 느껴집니다... 크나큰 사랑이... 넘치는 은총이! 도저히... 말로 표현할 수가 없어요..."
rows["115:2023187241"]="이 게임들 때문에 피곤해지네, 인간."
rows["115:2029470288"]="망할 놈들, 너희 영혼이 다 썩어오게 돼"
rows["115:2030466138"]="어떤 모험가들은 마법이 효과가 없다고 생각하지만, 내가 그들을 전투에 도전하면, 그들은 그들의 음성을 바꾸어 놓습니다."
rows["115:2048186663"]="우리는 세계 기둥의 조각들을 재조합하기 위해 필요한 모든 것을 해야 합니다.$B$B하지만 먼저, 우리는 그들 모두를 되찾아야 합니다."
rows["115:2061756169"]="쇼갈이 작업하는 무기에 대해 알아야 할 모든 것을 알아내야 합니다. 빨리 해야죠!"
rows["115:2076522138"]="라그나로스가 하야લના 소수 주민들에게 어떤 영향을 미쳤는지 이해한다면, 어떻게 복구해야 하는지 더 잘 이해할 수 있을 겁니다."
rows["115:2089418481"]="코브 신부님께 말씀드릴게요."
rows["115:211690826"]="힘은 여러 가지 형태로 나타납니다. 어떤 사람들에게는 무기이고 다른 사람들에게는 짐입니다."
rows["115:2119546705"]="엄마 브램블스타프는 내가 그녀의 방울을 끊지 않으면 도얀의 동굴로 보내겠다고 말했어요"
rows["115:2120296708"]="이제, 제 도전은 당신이 받아들이면 위험과 맞붙어 인내할 수 있는 능력을 시험해줄 것입니다."
rows["115:2134362053"]="|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s 공격 |cFFFF0000|Hspell:107018|h[Alexstrasza]|h|r!"
rows["115:2137666472"]="포털 사이트가 열렸습니다! 여러분의 노력 덕분에 우리는 이제 스톰윈드에서 트와일াইট 하이랜드를 빠르게 여행할 수 있습니다."
rows["115:223286866"]="당신 앞에 서선에 15명이 서있어요. 지금 여기 좀 바쁜데 알기는 힘들죠."
rows["115:224099557"]="그럴지도 모르지. 하지만 자네 증기 엔진이 날 날려 버린다면, 그걸 산산조각내 버리는데 어떤 포를 써야하는지는 잘 알고 있다고."
rows["115:256633829"]="|TInterface\\Icons\\spell_holy_consumemagic.blp:20|t%s는 캐스팅을 시작한다 |cFF00EEFF|Hspell:86622|h[Engulfing Magic]|h|r!"
rows["115:266947028"]="메하러에게 돌아가서 내가 그를 용서하고 그가 왜 그렇게 믿는지 이해한다고 말해"
rows["115:269948471"]="잠그라마르쉬에 있을 때 낚시를 좀 해보세요. 언제 다시 물 볼지 알 수 없습니다."
rows["115:278939836"]="에스코다르의 스킨 트레이너들은 가죽 노동자들과 함께 트레이더스 튜어에서 발견될 것입니다. 빛 - 안녕하세요"
rows["115:311529018"]="어둠의 힘이 그대를 이용하려고 기다리고 있도다, 메디브여! 이곳에 계속 머무를수록 끔찍한 일을 겪게 될 것이다. 시간이 얼마 없으니 서둘러야 한다!"
rows["115:31185050"]="그는 모그를 통합하고 다른 판다레인 인종을 정복했고 수천 년 동안 지속될 제국도 건설했습니다."
rows["115:312466773"]="거대한 상자, 가장자리에 총알로 가득 차 있습니다. 근처에 무죄로 앉아있는 요리 기름의 캔이 있습니다."
rows["115:313860287"]="먼저 서리한의 손아귀에서 탈출해야 한다. 그렇지 않으면 나처럼 저주받아 이 가증스러운 검 안에 영원히 갇히리라."
rows["115:327243666"]="시민 여러분, 파커 경비대장과 얘기해 주시기를 바랍니다."
rows["115:332579101"]="넌 정말 강해! 어렸을 때 우리가 이 일을 할 수 있을지 의심했을지도 모르지만 지금은 전혀 의심하지 않는다."
rows["115:345391068"]="좋아, 이번 달의 공예대회에 조금 더 추가할 예정이야"
rows["115:345882090"]="앞서 얘기했을 때, 당신은 그 용의를 갚을 것을 제안했었고"
rows["115:350094110"]="아페시스 크리스탈을 줘서 난 크리스탈 지오드 안에서 무기와 갑옷을 만들게"
rows["115:3525211"]="아무도 이 유물이 어디에 숨겨졌는지 모르지만, 호드는 먼저 그것을 손에 넣기 위해 모든 것을 하고 있습니다."
rows["115:359480351"]="여왕님과 의회는 최근 들어 울두아르에서 벌어진 재앙에 대해 논의하고 계십니다. 폭풍우 봉우리에서 무슨 일인가 벌어진 게 분명합니다!"
rows["115:367137141"]="그것은 거대한 규모의 마술을 수행 할 수 있는 능력을 부여하지만 그들은 빠르게 그 힘을 제어하는 능력을 잃습니다."
rows["115:392320633"]="프로스트울프 리lief Hut은 프로스트울프 킵에 위치하고 있으며, 프로스트울프 타워의 남쪽에 있습니다.$B$B얼라이언스는 현재 이 기구를 통제하고 있다."
rows["115:397512828"]="당신의 검색은 거의 완료되었습니다. 지혜의 계곡의 트롤 요새의 입구실에서 당신의 진실을 찾으십시오."
rows["115:405560027"]="내가 좋아하는 대로 이 일을 해내면, 내가 시간을 투자해 가르쳐 줄게!"
rows["115:41612833"]="난 그런 걸 주문하지 않을거라는걸 너희 둘 다 알고 있어"
rows["115:425731389"]="싸움을 덜 하고 농사를 더 많이 벌려$B$B'물론, 네가 싸운다면, 내가 지켜보는 건 싫다'"
rows["115:426879371"]="만약 당신이 우리의 해변에 가져오려는 전쟁이 있다면, 땅 자체가 당신의 열망과 폭력에 반응할 것입니다."
rows["115:434427016"]="여기를 방문하는 사람들은 공기가 너무 눅눅하다고 불평을 하지만, 사실 그게 내 빛나는 피부의 비결이지! 건조한 피부는 보기에 안 좋다고."
rows["115:435120800"]="그래. 난 내가 원하는 방식으로 이 세계를 떠날 것이다. 그리고 내가 돌아오면 총사령관님도 날 인정하겠지!"
rows["115:500057698"]="안토니오가 약병을 팝니다! 어서들 오세요. 이번에 가면 한동안 안 올 겁니다."
rows["115:502417871"]="20피트 높이의 칠면조가 거의 완성됐어요"
rows["115:503336875"]="왜소들은 가끔은 공격에 뒤집어 주죠"
rows["115:505817217"]="크리스탈 을 가까이 갈 때, 그 의 강력한 에너지 를 느낄 수 있습니다. 근처 에 있는 몇몇 스프리트 들 은 의심스러운 방향으로 빛나고 있습니다."
rows["115:515309099"]=" ⁇  부의 괴물들은 궁전의 발자국에 남아 있습니다."
rows["115:528607434"]="또한 아레나에 들어갑니다. 폭탄 상자를 가진 호젠! 그것은 마스터 붐 붐입니다."
rows["115:534080933"]="영혼 없는 혐오의 무궁무진한 군대가... 그런 기계에서 폭발할 폭력에 대해 생각하면 떨고 있습니다."
rows["115:585478478"]="거리의 남동쪽 끝에 있는 게로우스 엣 타버너 안에 있는 숙소관인 레네를 찾을 수 있습니다."
rows["115:593383726"]="용서하십시오, 노자리. 최근에 좀 예민해서 말입니다. 이 생물들은 시간의 길을 변형시키려고 하고 있습니다."
rows["115:602141719"]="난  ⁇ 이 되고... 그리고 내 잠자리도 너무 많이 들었어."
rows["115:606134708"]="알았네! 보다시피 이건 올루바 할머니께서 주신 선물일세. 할머니께서 드레노어 산 최고급 비단으로 직접 만드신 것이지! 내 자랑거리일세. 그렇고말고."
rows["115:621551501"]="제 선생님이 저를 학업에서 방해하는 게 아니었나요?$b$b아니면 내 인내심을 시험해 보려고 보내졌는지요"
rows["115:652991524"]="|TInterface\\Icons\\spell_arcane_blast.blp:20|t %s는 캐스팅을 시작한다 |cFFFF0000|Hspell:117914|h[Total Annihilation]|h|r!"
rows["115:66890249"]="보통 그런 폭발을 막아줄게 하지만 누군가 나트로와 카야미트 혼합물을 잘못 알고 있다고 생각합니다."
rows["115:67173978"]="그럴지도 모르지. 하지만 성스러운 땅이 아니더라도 이 파멸의 인도자로 네놈의 그 주인 잃은 심장은 충분히 찌를 수 있다."
rows["115:695560260"]="피멘토의 발가락이 돌을  ⁇ 어 대 용에 맞게 해줬어요"
rows["115:715240216"]="|TInterface\\Icons\\ability_rogue_envelopingshadows.blp:20|t%s 캐스트 |cFFFF0000|Hspell:117506|h[Undying Shadows]|h|r!"
rows["115:720713706"]="우리는 넘어진 여러분께 또 다른 기회를 줄 것입니다. 여러분은 자유롭지 않으므로, 그렇게 높은 기준을 가질 수 없습니다."
rows["115:726455316"]="별말씀을요, 앤빌워드 씨! 우리 블러드 엘프의 일에 이렇게 깊은 관심을 보여주시다니... 정말 뜻밖이로군요."
rows["115:749217303"]="내가 판매하는 것은 최고의 장비이고, 테스트되고, 진실이고, 가격도 정해져 있어, 거래하고 싶다면"
rows["115:749561864"]="이 재판에 있어서, 우리가 오는 환상에 직면할 때, 당신은 우리를 살아있게 해야 합니다."
rows["115:772067255"]="숙소는 건물에 들어서면서 오른쪽의 주요 층에 위치하고 있습니다.$B$B지도에 위치를 표시해 줄게요"
rows["115:773025964"]="더 좋은 걸 봤지만, 잠재력이 있어, 부인할 수 없어 주의를 기울여서 뭔가 배울 수 있을 거야"
rows["115:783432816"]="|TInterface\\Icons\\spell_shaman_improvedfirenova.blp:20|t 알리스라저는 |cFFFF0000|Hspell:99925|h[Full Power]|h|r!"
rows["115:815549654"]="아타스 왕자, 메이 빛 이 마을의 많은 사람들이 심각한 병에 걸리기 시작했으니, 도와줄 수 있나요?"
rows["115:829786098"]="결국 안도랄을 위한 전투를 벌일 것이고 우리 중 한 명이만 이 전장에서 승리하게 나갈 수 있을 것이다."
rows["115:835425069"]="오그리마에서 크로스로드로 가급품과 음식을 운반하는 일은 보직이었다. 요즘은 내 목은 항상 노선에 있습니다."
rows["115:846291479"]="고대의 해적 도수들을 조심스럽게 굴러오게 됩니다. 도수는 떨어지고, 4로 이어집니다."
rows["115:846359468"]="고대의 해적 도자 를 조심스럽게 던지면서, 도자 는 떨어지고 4로 이어지는 것 으로, 골격 해적 들 의 한 집단 은 그를 기 ⁇  을 내린다!"
rows["115:862365969"]="더 많은 효과를 얻기 위해 여러 가지 제품을 공급해 줄 수 있습니다."
rows["115:870288646"]="위험요소? 난 위험요소를 조롱한다!$B$B가장 맛있는 음식도 가장 위험한 음식이라고 아십니까?"
rows["115:873620320"]="그 후, 내일까지 기다려야 돼."
rows["115:874515351"]="이 세상 은 우리 눈 이 볼 수 없는 것 보다 더 많은 방법으로 손상 되어 있습니다. 심지어 시간이 지나면서도 어떤 면 에서도 다르게 느껴집니다."
rows["115:87499081"]="벨의 통계는 7:00 오후입니다. Venomspite에서 또 다른 생산적인 날이 밤이 우리에게 떨어지면서 끝납니다."
rows["115:884689118"]="밤 엘프는 다라란에 있는 포털을 제대로 확보하지 못했고"
rows["115:885266144"]="우리는 선배족입니다. 여러분들이 함께 하는 판다렌들은 단지 아이들이죠."
rows["115:88763014"]="아이사 연습하는 시간은 너무 많지만 그 결과는 부정할 수 없습니다."
rows["115:89803547"]="타리가 이 비행에서 문제를 해결하기 전까지는 캐피시토리움은 추가 연료가 필요할 겁니다.  5 부대가 해야 돼!"
rows["115:905256071"]="|TInterface\\Icons\\ability_rogue_shadowdance.blp:20|t%s는 |cFFFF0000 부패한 추종자|r를 불러서 그를 돕기 시작합니다!\010"
rows["115:907111956"]="내가 당국에 가서 운이 좋으면 전염병이라고 말해주고 우리 모두 죽을 거라고"
rows["115:90736767"]="네, 나그란드에서 나가서 그 지역의 요소들로부터 배울 것입니다. 그들은 고통 받고 같은 증상을 많이 보았습니다."
rows["115:915634890"]="이 힙오그리프들은 에크소다르 근처에 잘 관리되어 있어"
rows["115:919785742"]="지금 일어나는 일은 우리 모두를 영향을 미칩니다. 모든 사람들의 도움이 필요합니다. 우리는 함께 침략을 맞서 싸워야 합니다."
rows["115:947808963"]="아타말 수정 7개의 힘이로군! 생존자가 더 있다니! 자나, 당신인가? 당신을 다시 보게 되어 정말 반갑군!"
rows["115:950351930"]="아타스는 그의 엄청난 잔인함으로 내 몸과 정신을 끊어 버렸고, 스컬지 군대에 봉사하기 위해 저를 반시처럼 키웠다."
rows["115:962013295"]="내가 배를 만들고 있다는 걸 알 수 없지?"
rows["115:962059177"]="모두 진정하십시오! 우리는 이 상황을 통제하고자 온 힘을 다하고 있습니다. 저 피눈물 오크 녀석들은 무자비한 자들입니다!"
rows["115:963358876"]="이 계곡의 물이 전설적인 \"청소년 수영장\"이 될 수 있을까?"
rows["115:989273567"]="난 그 전에 봤어 - 나그란드에서 그가 워크시프의 망트를 내려놓지 않자 훈련 중에 다시 봤어"
rows["115:991842363"]="스톰파이크 구호소는  ⁇  발더에 있습니다  ⁇  발더 바라크 바로 바깥에 있습니다$B$B호드는 현재 이 기구를 통제하고 있다."
rows["116:1017649390"]="네가 필요한 만큼 오래 걸리 고엘, 볼진이 그의 사람들이 위험에 처해 있다고 믿는다면"
rows["116:103067124"]="천상의 존재들을 마주하면 당신의 결단력이 시험되고, 당신의 능력을 의심하고, 당신의 위대함을 불러일으키게 될 것입니다.$B$B준비됐어?"
rows["116:1033352476"]="바보 같으니! 왕자의 부하들은 현재 우리가 동맹을 맺은 바로 그 포세이큰이었고 이제 그 왕자가 우릴 배반했소!"
rows["116:1044521393"]="물러서, 괴물, 싸우려면 내가 싸우기 때문에$b$b너희들 중 어느 하나라도 싸울 거야"
rows["116:1053071588"]="내 형제들과 저는 며칠 안에 북쪽 길네아스까지 배를 타고 갈 수 있습니다. 바로 수리 작업을 마치면 말이죠."
rows["116:1066719588"]="제이즈, 네가 이 자리에 있을 때 페리시에게 마사지를 해주면 좋겠어?"
rows["116:106949650"]="콜린이 정상에 있을 때  ⁇ 그루트 오그스가 스탠더머를 공격했고,"
rows["116:1082587561"]="물의 원자 중 한 귀족인 히드라시스가 불의 종들과 전쟁을 벌이고 있다고 들었습니다."
rows["116:1129175208"]="아빠는 더 큰 먹이를 찾아 더 이상 다른 곳으로 떠났어 걱정마, 우린 여전히 사냥중이야"
rows["116:1132668764"]="가로쉬의 사례는 제가 따르려는 것이 아닙니다. 얼라이언스은 스스로 결정을 내려야 합니다."
rows["116:114160082"]="자넨 좀 자부지 마, 너만 도와줘서 이 놈들이 지금 내 머리를  ⁇ 고 있을 거야"
rows["116:118234438"]="이봐요, 레이  ⁇ 은 제국 건설이 얼마나 쉬운지"
rows["116:1187124429"]="너희 종교재판관은 아무것도 아니다. 붉은십자군 녀석들아! 아무도 스컬지의 손아귀를 벗어날 수 없다!"
rows["116:119769799"]="자 ⁇ 슨, 우리 커버를 깰려고 해?"
rows["116:1200387085"]="스컬지가 모든 구역에 침투했다! 성스러운 빛이 이 역겨운 것들을 물리쳐 주시기를! 우리는 끝까지 싸울 것이다!"
rows["116:1212205952"]="그런가요? 흥미롭군요. 잠시 나가서 화장이라도 고치고 오는 것이 어떻습니까? 저는 생각할 것이 좀 많습니다."
rows["116:1217232280"]="|TInterface\\Icons\\spell_shadow_shadetruesight.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:82299|h[Fester Blood]|h|r!"
rows["116:1223158497"]="우리들의 길은 정해져있었고, 우리는 우리의 가장 큰 적이었고,"
rows["116:1269231579"]="왜냐하면 그들은 철로 만들어졌기 때문입니다."
rows["116:1274407925"]="당신 실패에 대해 평화유지군을 비난하고 있습니까? 간단한 임무가 당신에게 맡겨졌습니다. 트롤은 분명히 사기꾼이었습니다!"
rows["116:1276179342"]="난 폰치야, 전 공원을 청소하고 새끼를 돌봐요."
rows["116:1282909190"]="평가 오류를 최소화해봐요, 이번 달 또 다른 보석 배송에 과금 지불했다고 게제에게 말해주면 안 돼요"
rows["116:1286190428"]="또 다른 공격이?\010이 영돌들은 우리가 타운롱으로 밀어내기 전까지는 굴복하지 않을 거야"
rows["116:1286309792"]="분노 없이 사는 것은 전혀 살지 않는 것이 아니라 우리 스스로에게 달려 있습니다. 우리의 분노를 물리치면 우리는 큰 힘을 얻습니다."
rows["116:132904671"]="대라란 북부에 있는 우물이 있는데, 이 도시의 모험적인 방문객들이"
rows["116:1345934563"]="당신은 타이틀을 넘어서서 더 이상 전투여왕이 아니지 마 니 새 왕관을 가져라 아즈하라의 챔피언인 나르지라"
rows["116:1351989975"]="가로쉬 지옥의 잔해가  ⁇ 은 에너지로 인해 손상되었습니다."
rows["116:1356315855"]="영웅들이여, 그대들은 길을 뚫어 성채 안 구출 지점을 확보해야 하네. 성루에서 그대들과 합류하겠네!"
rows["116:136752076"]="14,000년 전, 이 땅 전체가 \"Mogu\"라는 끔찍한 군주들의 인종에 의해 통치되었습니다."
rows["116:1369087756"]="이들은 우리의 스카우트들이야, 그들은 이미 어두운 포털을 통과해 왔고 새로운 세계 소식을 가지고 돌아왔습니다."
rows["116:1378352929"]="|TInterface\\Icons\\spell_shadow_twilight.blp:20|t%s는 캐스팅을 시작한다 |cFF006EFD|Hspell:103754|h[Twilight Epiphany]|h|r!"
rows["116:1397662390"]="$P화이트 타이거의 사원에 오신 것을 환영합니다!  ⁇ 은 놀라운 토너먼트를 운영하고 있습니다."
rows["116:1415171942"]="조심해 해안에서 사우스 시 해적들이 있다고 들었어요$B$B내가 직접 확인해봐야지"
rows["116:1420122617"]="하지만, 콜티라, 우리는 더 이상 형제가 아닙니다. 당신은 이제 호드의 일원이고, 나는 얼라이언스의 일원입니다."
rows["116:1423856186"]="카오스의 표지판은 레븐하일드의 거야, 짐승!"
rows["116:1433300297"]="누가 도착했을 때야 왜 그렇게 오래 걸렸어?"
rows["116:1453124872"]="우리는 며칠 동안 여기 갇혀있었고, 우리가 깨질 지점에까지 뻗어있었지만, 정신을 고쳐두기 위해 최선을 다하고 있습니다."
rows["116:1462852144"]="프로스트울프 묘지는 도로 옆에서 프로스트울프 마을에서 북쪽으로 멀지 않습니다.$B$B어느 쪽도 통제하지 못해요"
rows["116:1472326361"]="또 한 번 망하면 카프티즈의 테스트를 위해 포털을 통과할 거야"
rows["116:1489474876"]="그는 루닉 판에 쓰여진 글의 일부를 해독했다고 보고했지만, 그가 번역을 녹음한 것 같지 않습니다."
rows["116:1532660352"]="이 생물은 조상의 그리모테마로부터 힘을 얻고 있습니다."
rows["116:1550927187"]="당신이 찾는 것은 게니아 루네토테마의 조언입니다. 당신은 마을의 동쪽에 있는 큰 텐트에서 그녀를 찾을 것입니다."
rows["116:1562856408"]="스킨너들이 훈련에 필요한 건 아니지만 준비되면 가르쳐 줄 수 있을 것 같아요"
rows["116:1563837058"]="솔직히 말해 키린 토가 어떻게 생각하든 난 전혀 관심이 없소! 그들은 구시대적인 방식만을 고집하는 바보들이라오."
rows["116:1573453879"]="상자가 제가 손에 들어올 때만 가져갈 겁니다. 저는 여러분의 동료들이 매우 깨달음을 얻으실 것이라고 확신합니다."
rows["116:1577628184"]="이 곳은 안전해야 했잖아 기술공 오직 한 분만 알 수 있습니다!"
rows["116:1590763923"]=" ⁇  발다르는 마지막에 큰 타격을 입었다 호드 재건과 수리할 수 있는 물품이 더 필요해요!"
rows["116:1598537296"]="내가 행운을 더 많이 내게 해줘서, 물건 하나 가져와"
rows["116:1612695472"]="이 동굴 밖에서 나가가가 많이 들어 있습니다.$b$b우리는 이 곳에 눈에 띄지 않게 도착하는 행운이었습니다."
rows["116:16398078"]="아주 많이 희생될 겁니다. 옛 신들의 전신이 다시 땅을 돌아다니기 전에요."
rows["116:1641880720"]="우리는 잠시 머물렀다 다시 탑으로 돌아가야 합니다. 우리와 더 얘기를 나누고 싶다면 그곳으로 오시기 바랍니다."
rows["116:1646266316"]="에스비나가 네 동물 동반자를 돌보는 게 행복해지겠네"
rows["116:164664218"]="그대의 설명을 들어 보니, 앞서 온 이에게 빌려준 책을 보면 그 무기가 무엇인지 쉽게 알 수 있을 듯하구나."
rows["116:1662245803"]="나 같은 다른 사람들도 있습니다. 모든 시대의 파라곤들이, 시간 속에서 얼어붙고"
rows["116:1679146996"]="물고기가 올라갈 길이나 산이 없다는 것은 매우 슬픈 일입니다. 더 많은 물고기 친구를 가져오면 그들이 행복할 것인가?"
rows["116:1713142115"]="우리는 오크스 호드, 진인 호드. 우리는 죽습니다, 피가 흘리고 전투장에서 찌르고, 진정한 오크처럼."
rows["116:1716670058"]="수중의 퀸테스센스  ⁇ 이 필요해요, 히드라시스, 왜냐하면 난 화산 심장부에 가서"
rows["116:1724947579"]="또 다른 존경자, 내 명성은 내보다 앞서있지$B$B걱정 마, 언젠가는 너와 나 함께 갈지도 몰라"
rows["116:1736686400"]="광산업자들은 실버문 시티 내에 있고, 그들은 그들의 이익을 향하는 불쾌한 요금품 근처에 있는 것 같습니다."
rows["116:1742869285"]="이 고물을 고치면 도적들한테 습격받을 걱정 없이 장사를 다닐 수 있을 거야!"
rows["116:1805681100"]="그녀는 지식과 언어 능력을 유지하고 있고, 당신을 위해 혼자 힘으로 임무를 수행할 수도 있어요. 정확히 어떻게 한 거예요?"
rows["116:1865816005"]="이 콰일디르의 두개골은 바위처럼 강하다"
rows["116:1870633492"]="그럼 내가 기억하네, 우리는 이 숲에서 가장 강하다. 우리는 나무의 왕이다. 우리는 우리의 적들에게 죽음이다!"
rows["116:1887441960"]="여동생: 호기심이 당신을  ⁇ 다면, 당신은 당신의 구원은 북녘골의 막시밀리안에게 제공되었다는 것을 알 수 있습니다."
rows["116:1890330756"]="이 모든 거칠고 귀찮은 웃음을 참을 수 없어 리돈의 한 마리가 더 이상 우리 모두를 쏴버릴 거야\010"
