rows["116:1922372335"]="부탁해줘서 반가워요."
rows["116:1928141602"]="아이스윙 벙커는 얼라이언스 영토와 전투장 사이의 경로를 보유하고 있습니다.$B$B호드에 의해 통제됩니다."
rows["116:1937456479"]="만약 당신이 나에게 물어보면, 광부보다 더 큰 직업은 없다. 그리고 만약 당신이 나에게 물어보면, 왜구보다 더 큰 광부도 없다!"
rows["116:1973617172"]="마그테리돈, 일리던 그리고 펠 오크들이 이 거룩한 곳에 끼친 피해를 복구하기 위해서는 많은 세월이 걸릴 것입니다."
rows["116:1985093353"]="랜저들은 햄노비아에서 수업을 듣습니다. 햄노비아는 팔콘윙 스퀘어 북동부 건물에 머물고 있습니다."
rows["116:2001683010"]="이 에너지는 그들의 정신을 갇혀서 실패를 다시 살아가고 있습니다."
rows["116:2005074786"]="아분이 감히 나와 맞서겠다고?! 가만두지 않겠다! 내가 드레나이를 처리하면 그들은 차라리 잃어버린 드레나이이길 바랄 것이다!"
rows["116:2018580951"]="군인 여러분, 여러분 이 성취를 보세요! 레지온의 가장 무서운 기계도 호드와 비교할 수 없습니다!"
rows["116:2030470171"]="스톰윈드의 공원 구역이 도시를 지나가는 데스윙에 의해 파괴되면서, 우리는 잠시 동안 다르나서스로 돌아갑니다."
rows["116:2082879930"]="미래는 두 분에게는 안좋은데, 만약 여러분이 관계를 잘 풀면"
rows["116:2088734408"]="여러분, 필사자들은 알리스라를 기억할 수 있습니다. 되살아난 자불꽃으로 태어난 거야"
rows["116:2101316416"]="이게 다 뭘 위한 것이냐? 하찮은 것을 위한 거란 말인가? 넌 너무 늦었다. 준비는 이미 끝났으니 말이야. 곧 주인님께서 귀환을 하실 것이다."
rows["116:2103531212"]="오토 그레이하이드는 장로회에서 많은 시간을 보내죠."
rows["116:2117023114"]="조심해, 불안정하고 빨리 힘을 잃어 버립니다. 빨리 사용하세요!"
rows["116:2130559191"]="어버스롱 동부에서 수련을 하고 있는 이더스트라이더들은"
rows["116:257419226"]="의심은 약한 사람들 뿐이지, 너의 힘을 의심하지 마, 이시. 우리는 살아남을거야, 왜냐하면 우리가 해야 할 것이기 때문이다! 호드는 승리할 것이다!"
rows["116:289047947"]="당신도 날 죽이러 온 거라면 그리셀다에게 뭔가를 먹일 때까지 좀 기다려 주지 않겠소? 불쌍하게도 벌써 며칠째 아무것도 먹지 못했다오."
rows["116:291875598"]="우리는 이미 기기에 살아있는 에너지를 포착하는 모가 능력을 알고 있습니다. 이것은 우리가 더 많은 것을 알아야 할 마법이 아닙니다."
rows["116:29207449"]="여기 있어, 내가 방금 문을 알아냈어, 준비되면 알려줘서 열게 될 거야"
rows["116:312803115"]="당신 목숨으로? 당신은 내 형제가 아니니, 이 곳에서 떠나서 다시는 우리 땅에 발을 들여놓지 마!"
rows["116:327302682"]="제 아내가, 영들이 인도하는 것은... 이  ⁇ 쟁이들과 거꾸로 돌아다니는 우리 사업이 안되어서 다행입니다!"
rows["116:333890319"]="동상은 모두 원래 위치로 돌아갑니다.$B$B이제부터 순서대로 다시 시작해야 합니다.\010"
rows["116:335471401"]="아르헨트 십자군은 더 오래 기다릴 수 있고, 또한 손님들은 곧 카라반에서 내려가야 할지도 모릅니다."
rows["116:343048415"]="물론, 그는 작은 것 같지만, 그놈 기준으로는 작지만, 진짜 질문은 그가 무엇을 기억할 것인가?"
rows["116:344431665"]="알렉스스트라사스가 죽음의 날개에 대해 판단을 내렸다고 이해했지"
rows["116:344816902"]="우리가 해냈습니다! 알갈론보다 먼저 도착했다고요. 아마 시스템을 조작하면 알갈론의 분석을 방해할 수 있을..."
rows["116:346048903"]="꿈의  ⁇ 이 당신이 원하는 것을 보여주기 위해서는, 당신은 내면의 조화를 이루어야 합니다."
rows["116:348967511"]="모가들은 두려움으로 통치했고 공포는 그들을 권력을 유지시켰습니다."
rows["116:358489770"]="그의 말이 옳습니다. 그런데 그 멋진 문구는 앞으로 제가 써야겠군요... 이제 그는 쓰지 못하게 됐으니까요!"
rows["116:36591774"]="우린 더 많은 참전용 Shado-Pan이 필요해 우리가 대결하기 전에"
rows["116:379376774"]="쉐도파인 피의 맹세를 함께 했잖아요?"
