rows["116:405442961"]="이 지식 부족은 많은 사람 가운데 또 하나의 약점이며, 죽음 자체의 힘에 대한 희망이 거의 없습니다."
rows["116:418657122"]=" ⁇ 드린은 실버문의 기일드 마스터입니다. 그녀의 거주지는 마지스터 게이트 근처의 노인 거리를 따라 있습니다."
rows["116:421670947"]="싸우는 놈이나 쓰러진 놈 가리지 않고, 적의 기운을 빼앗아버리면 더 작은 존재들이 나가떨어지는 곳에서도 우리가 버틸 수 있다."
rows["116:423084558"]="대사장이 죽고 해안이 깨끗하면 알려줘서 내 보고서를 담아 피경찰에 다시 올게요"
