rows["116:52910143"]="난 더 이상 죽음의 기사들을 훈련하지 않는다. 난 멍청한 초신자들과 그들의 끊임없는 질문들을 지쳤어.$B$B이제 시작해"
rows["116:531014926"]="아쉽게 보셨죠, 어제보다 조금 더 잘됐어요."
rows["116:550526431"]="감염된 야간추행자  ⁇ 은 북쪽에서 왔어요"
