rows["116:564824697"]="아치 드루이드는 용들이 고대에서 노르드라시일에 놓았던 것처럼 용들에게 축복을 청했습니다."
rows["116:60914712"]="그 블러드 엘프는 마법학자처럼 보이지는 않지만 탑의 저주를 풀 수 있는 물건을 지니고 있는 것 같습니다."
rows["116:622821398"]="운하에 악어가 있다는 거 알지? 누군가 애완동물로 삼으려고 늪에서 데려왔다가 버린 거래."
rows["116:64065541"]="이 회색색 사다그는 승무원 중 가장 오래됐지만, 그 중에서도 가장 단단한 놈이야!"
rows["116:68248525"]="넌 약해, 아픔이 없어서 네 삶이 빼앗겨질 거야"
rows["116:708968595"]="내가 살면 곧 크리스탈의 힘으로 날 섬길 거야"
rows["116:712092127"]="불꽃을 가져오세요, 사령관 캠프를 파괴할 겁니다"
rows["116:725775568"]="그리모테마 경매 서비스를 이용하려면 위대한 마가타 그리모테미의 허락이 필요합니다!"
rows["116:740387211"]="스테파노스는 우리의 히포그리프 마스터입니다. 그는 에크소다르의 중심 중심지에서 살고 있습니다. 빛 여행에 축복해"
