rows["116:782336021"]="실바나스, 같은 실수를 두 번 하지는 않을 것이다. 이번에는 탈출할 수 없다. 모두 죽음으로 나를 섬기리라!"
rows["116:794434250"]="개인 강성은 중요하지만 부족 강성은 더 중요해 우리 부족은 가장 약한 구성원만큼 강하다"
rows["116:809111094"]="꿈에 빠져있었는데 그의 생명력을 감지하지만 아직 연락할 만큼 힘이 커진 게 아니었어"
