rows["117:1804839881"]="내가 도와주지 않으면 무기 전문성을 잊어야 해 윈터스프링의 에버룩으로 가서 도움을 찾아라"
rows["117:1834200829"]="하지만, 난 화재의 연기로 그들이 볼 수 있는 것은 당신의 실루엣뿐인 것 같아요."
rows["117:185180216"]="남쪽 젤펠린 타워 안에서 이상한 오크들이 속삭이는 소리를 듣는데"
rows["117:1855815248"]="저 망할 농민들이 더 빨리 일해야 돼 아이언포지아내와 아이들을 그리워 "
rows["117:1863336207"]="\"...이퍼포칼 거리에서 집중하면 이 거리의 절반에서 무한까지 최대 날카를 보장합니다\"..."
rows["117:188438415"]="마을 사람들은 에버스톤을 되찾았기에 감사했습니다. 그들은 우리에게 포세이큰에 대항하기 위해 작은 무언가를 가져왔습니다!"
rows["117:1912166795"]="제가 처했던 상황을 되돌릴 주문을 연구하던 중이었고 이제 거의 다 찾았... <끄아아악> 이런!"
rows["117:1920977436"]="잠깐만요, 그냥 보조예요."
rows["117:1929142495"]="내가 왜 날름이 사냥을 좋아하는지 곰곰이 생각해 봤지... 다른 사냥감처럼 멍청하지 않아. 제대로 싸울 수 있거든."
rows["117:1937579439"]="한데 자연의 수호자인 우리 드루이드는, 만물에서 조화라는 핵심적인 면을 간과하는 게 아닌지 의구심이 들 때가 있소."
rows["117:1940528053"]="난 이곳에서 할 일을 명받고 머물면서 스톰윈드의 깃발 아래 싸우고 있소. 하지만 이곳에서 내가 하는 모든 일은 공허하오."
rows["117:1943132669"]="거의 다!$b$b안구름에 있는 술집에서 차가운 구덩이가 기다리고 있어"
rows["117:1951843222"]="|TInterface\\Icons\\spell_nature_callstorm:20|t%s는 |cFFFF0000|Hspell:138732|h[이온화]|h|r로 적들을 괴롭히고 있다!"
rows["117:195295570"]="어넷 윌리엄스, 서쪽에서 훈련된 박쥐를 타고 갈 수 있어요"
rows["117:1954695285"]=" ⁇ 투기와 안개가 짜는 걸 혼자만 할 수 있어"
rows["117:1956745645"]="만약 당신이 노스렌드로 여행하고 있다면, 빙하 해체 노스스피어는 여기서 발가르데로 갈 것입니다."
rows["117:1964843313"]="만약 당신이 대장님의 존경을 얻었으면, 뭔가 있을 거야."
rows["117:1983704736"]="너네 쥐들이 정말 날 아프게 해... 내가 너랑 충분히 놀았어... 이제 그 무덤의 복수를 맛봐!"
rows["117:1987483678"]="당신은 적외선 빛의 목표입니다. 팀 동료들과 함께 무대를 돌아다니며"
