rows["117:2027574455"]="기다려줘서 미안해, 걱정이 많다는 걸 알아요."
rows["117:2050064453"]="이 곳이 얼마나 싫었는지 알잖아 왜 날 불러왔어?"
rows["117:2070347149"]="나이를 먹은 것 같아서 예전처럼 움직일 수 없어서"
rows["117:2075712183"]="제 마법을 사용하면 스랄이 죽기 전으로 시간을 되돌릴 수 있답니다. 하지만 제가 시간을 조절하는 데는 한계가 있다는 걸 알아 두십시오."
rows["117:2089414153"]="굴단 님은 진실을 말씀하신다! 우리는 즉시 돌아가서 형제들에게 이 소식을 알려야 한다! 차원문을 통해 돌아가도록!"
rows["117:2093400424"]=" ⁇ 어뛰는 조카퍼스! 우리는 그것을 찾았어요! 우리는 정말로 그것을 발견했습니다. 그것은 노인 틸스의 숨겨진 보물입니다! 오 소년 오 소년 오 소년!!!"
rows["117:2096931514"]="샤 아말가메이션은 캐스팅을 시작한다 |cFFFF2222|Hspell:139382|h[이치없는]|h|r! 그것을 막기 위해 앵무새 중 하나를 방출하십시오!"
rows["117:2100654042"]="정말 독특한 표본이 많아서, 저는 지역 식물과 동물에 대해 더 열심히 연구해야 합니다."
