rows["117:2112251415"]="이럴 수 없다면 다우너의 꽃에 있는 모든 사람들에게 당신이 맥주보다는 와인을 좋아하는 큰 닭이라고 말할 겁니다!"
rows["117:2124970796"]="동부 왕국에서 더 빠른 기리폰은 델사마르에서 발견할 수 없습니다!"
rows["117:2136947784"]="술에 걸리는 남자가 좋아지거든 매일 밤  ⁇ 을 당해서 내 용서를 키워왔어"
rows["117:2137009518"]=" ⁇ 이의 저주로 유명한 그린스톤 맥주도 우리에게 반발했습니다!\010그의 하자가 피해를 입지 않은 작은 것을 훔쳤다."
rows["117:219297186"]="우린 불길을 가릴 때까지 아후네의 하위군들을 살아남아야 해"
rows["117:237315155"]="로르테마르의 어리석은 짓이 그의 부상을 일으켰고, 켈레델러는 선택되지 않고 주인만을 선택한다."
rows["117:274610714"]="제가 현장에서 있을 때 제 위치를 알려주지 마타스는 여기서 무슨 일이 일어나고 있는지 알아야 합니다."
rows["117:285448998"]="감히 여기까지 와서 살아있는 불꽃의 비밀을 캐내려 한단 말이냐! 그 무모한 용기를 후회하게 되리라."
rows["117:331883711"]="함정이 터지면 아무도 갇힌 사람들이 완전히 죽기 전까지는 들어와 나오지 않습니다."
rows["117:333224148"]="난 너무 아름답고, 이 총을 봐 금을 봐"
rows["117:350623863"]="이 성전에서 정말 큰 도움이 됐어요!$B$B고장지사가 당신이 도착했을 때 기뻐한다고 말했죠."
