rows["117:376653417"]="Shadowfang Keep에서 가져온 자료는 흔한 물건이 아니죠."
rows["117:385721831"]="스노프폴 묘지는 윈터엑스 홀드의 동쪽에 있는 전투 현장에서 언덕 꼭대기에 위치하고 있습니다.$B$B어느 쪽도 통제하지 못해요"
rows["117:402252238"]="너무 가까이 접근하지 마시오. 딱 한 번이었지만... 전에 그 물건에 손을 올린 적이 있소이다. 지금도 그때 생각이 생생하구려."
