rows["117:514586554"]="샤의 초신으로부터 사람들을 지키려면 많은 것을 배워야 합니다."
rows["117:536183351"]="마가타와 그녀의 친척들은 도시를 떠나고, 당신의 유산을 품은 귀한 아들이 있습니다."
rows["117:569410344"]="내 안의 어둠의 구멍이  ⁇ 어졌어 다시 볼 수 있고, 내 구원자의 얼굴을 볼 수 있어"
rows["117:599185745"]="그녀는 너무 멀리 갔어요. 저는 얼라이언스가 그들의 전쟁 마법사를 도시로 이동시킬 수 있다고 확신합니다. 그 인간... 마녀!"
rows["117:637842101"]="어... 여기 어딘가요...? 이 무슨 악몽을 꾼거지... 하지만 곰곰히 생각해 볼 시간은 없어요. 보고해야 할 정보가 많습니다!"
rows["117:657133935"]="스톰파이크 장군은 쓰러졌어 전투는 승리로 끝났습니다$B$B이제 얼라이언스가 잃어버린 재산을 되찾기 위해 달려가는 동안 웃으십시오."
rows["117:659133517"]="스컬지가 우리를 포위했네. 얼마간은 마을을 방어할 수 있겠지만, 결국 저들을 물리치지 못한다면 우리는 모두 죽을 걸세."
rows["117:709421638"]="이봐, 이 집 좀 봐요, 정말 좋은 농장이죠."
rows["117:719035801"]="움직이지 말고, 미리 생각하고, 위험은 크게 경계해야 하며, 이 실험을 완료하기 위해 20의 얼음의 본질을 수집하라."
rows["117:73033406"]="우리는 맨티드, 야롱, 모구와 싸우고 적들이 각쪽에서 우리를 마주하고 있습니다.\010깜짝 놀랄 일이 없도록 왔어요"
rows["117:733894401"]="어기기 위해 불행한 날이 될 거야 나쁜 날 낚시하는 게 좋은 날 일하는 것보다 낫다"
