rows["117:82761182"]="크로시크는 크로스의 피입니다. 우리는 크로스의 선택의 백성입니다.$b$b그의 힘으로 우리는 결코 죽지 않을 것입니다."
rows["117:833112356"]="용감한 사람들의 홀에 가세요. 이저스노우베인이 아라티 계곡에 도착하는 데 도움이 될 것입니다."
rows["117:852699761"]="난 영원히 너를 사랑할 것을 맹세한다. 죽음은 그것을 지울 수 없다."
rows["117:914868531"]="내가 티콘드리우스에게 사랑을 갖지 못한다고 말해서, 내가 섬기는 신께서... 레지옹의 멸망으로 이익을 얻으실 것입니다."
rows["117:916915432"]="하지만 외모는 당신 같은 사람들을 속이는 것 같네요 걱정마, 난 당신의 전투 스타일을 선호하는 걸 만들겠습니다."
rows["117:918181848"]="함께 성전을 되찾고 이 마을 사람들에게 희망을 돌려줄 수 있어"
rows["117:918315671"]="이 룬스톤에 따르면 모가들은 티탄의 구조물이었는데 돌로 만든 영혼 없는 존재였죠"
