rows["117:937386048"]="이제 우리는 더 많은 희생자를 요구하지 않는 그런 파괴를 방지하기 위해 우리의 노력을 집중해야 합니다."
rows["117:955350585"]="실버윙 홀드는 여러분의 도움이 필요합니다. 스톰윈드  ⁇ 에서 엘파란과 이야기하십시오."
rows["117:961082476"]="|TInterface\\Icons\\ability_vehicle_sonicshockwave.blp:20|t%s는 |cFFFF0000|Hspell:103678|h[결파의 미덕]|h|r!"
rows["117:969853181"]="그리고 맥주 모두 빠진 때\010Shadowforge로 뛰어들게\010래그나로스에게 쓴 잔을 드리고...\010...하지만 그에게 한 방울도 안 가져오세요!"
