rows["118:1022243151"]="이거 보라고. 결합 구조가 약하잖아. 주문을 끝까지 외우지 않으면 이런 게 나오는 거야."
rows["118:1036989729"]="다음은 여군주 블라미우스이다. 암흑의 힘으로 살아있는 자의 영혼을 뽑아 탐욕스럽게 흡수한다고 하지."
rows["118:1047408606"]="저는 열렬한 희망으로 빛를 잿빛 골짜기에서 포세이큰로 데려갈 수 있을 것입니다."
rows["118:1056228613"]="이것은 휴일이 아닙니다. 우리의 마음과 영혼은 우리를 묶는 중독으로부터의 마지막 탈출이 바로 켈레다나스입니다. "
rows["118:1062665011"]="크리스탈을 잘 흔들려봤나?"
rows["118:1074937539"]="스피릿스 밸리의 다크브라이어 로지에서 페프레도와 이야기해"
rows["118:1099827474"]="대사님, 전 군부에게 말했듯이, 제 충성심은 의심의 여지가 없었습니다."
rows["118:1099892480"]="내가 왜 여기 온 건지 말해줘야지$B$B당신은 죽음의 날개에 대해 알고 있습니까? 오닉시아?"
rows["118:1109198538"]="내 최고의 챔피언들이 너의 무례함을 당할 거야"
rows["118:1113781382"]="이 심야의 모든 사람들 중, 당신은 이것을 내게 줬어요."
rows["118:1118492628"]="너 어떤 존재야?$b$b<파다렌은 멈추고 그녀의 눈은 넓어지고 있습니다.>$b$b내... 그 아름다운 녹색 피부를 봐!"
rows["118:1127121882"]="강수와 그의 조교는 전사 테라스에서 일하고 있습니다."
rows["118:115349511"]="너 자비에 뱉으면 아무도 안되니, 살인을 원하냐? 가로쉬는 그 어느 때보다 많은 피를 얻을 거야!"
rows["118:1160317570"]="이 사실을 알고, 내가 가만히 있을 수 없을 것입니다 호드 이해관계가 내 백성들과 충돌하고 있습니다."
rows["118:1162154922"]="오벤 라지클라우는 서방 방의 이중 다리에서 거주하고 있으며, 바로우 덩어리에서 나오는 통로 근처에 있습니다."
rows["118:1179125608"]="색상 은 그 사람 에게 대조적 인 차이, 깊이, 가치, 음색 을 알려 줍니다. 색채 의 단순한 변화 는 사람 을 웃거나 눈물 으로 이끌 수 있습니다."
rows["118:1180499175"]="너희 둘이 날 도와줘서 좋은 일을 했으니, 내가 먼저 투표해 줄게"
rows["118:1213597419"]="|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t%s는 캐스팅을 시작한다 |cFFF00000|Hspell:117436|h[라이트닝 포로]|h|r!"
rows["118:1228573134"]="대사령관은 이 병들을 당신에게 줄 것을 요청했고, 호드에 대한 우리의 노력에 동참해달라고 요청했습니다."
rows["118:1231879179"]="추가로, 장로들은 각각 프레이야의 주문 공격력, 물리 공격력, 소환수 능력의 증대와 연관되어 있음이 드러났습니다."
rows["118:123241062"]="도착할 때 우리 비행기를 잃었으니 부끄러운 일이죠."
rows["118:1232642850"]="|TInterface\\Icons\\spell_nature_lightningshield.blp:20|t%s는 캐스팅을 시작한다|cFF1CF2FE|Hspell:79900|h [불안한 방패]!|r"
rows["118:1240610339"]="위험 을 피하는 것 은 우리 의 본성 이 아닙니다. 우리 가 사랑하는 사람 들 을 보호 하는 것 이면, 어둠 에 빠져나갈 것 이다."
rows["118:1241970537"]="|TInterface\\Icons\\ability_warstomp.blp:20|t %s 캐스팅 시작 |cFFFF0000|Hspell:127480|h[크루싱 슬램]|h|r!"
rows["118:1268862730"]="난... 잘 모르겠다, 브란. 여기 너무 오랫동안 있었어... 이전의 삶에서 기억나는 것이라곤 섬뜩한 순간들과 악몽뿐이야."
rows["118:1278980442"]="|TInterface\\Icons\\spell_fire_elemental_totem.blp:20|t%s |cFFFF6F00|Hspell:75218|h[불의 소환]|h|r!"
rows["118:1289669437"]="그만! 너희 그걸 전투라고 하는 건가? 형편없군! 제대로 한번 싸워 보라고, 아니면 끝장날 줄 알아!"
rows["118:1307551453"]="|TInterface\\Icons\\spell_shadow_shadesofdarkness.blp:20|t%s는 그를 돕기 위해 |cFFFF0000 암흑 창조물|r을 초청하기 시작합니다!\010"
rows["118:131386376"]="알터랙과 힐스브래드는 다시 법정 지배에 들어올 것입니다."
rows["118:1318937129"]="지금, 지금, 지금, 도시 한가운데에 拳을 올리는 행운이 안 났어요."
rows["118:1325945095"]="- 네 말만 남기면 스컬지 이 경우 성공하면 얼라이언스' 즈음의 ' 리치 왕  ⁇ 은!"
rows["118:1341640319"]="볼진과 처음 이 땅에 왔을 때 기억나지 호드은 단지 아이디어였어 희망이었어"
rows["118:1344696493"]="세나리온 드루이드가 불꽃날개 거점을 점령했다는 소식을 외부에 있는 우리 정찰병이 전해왔습니다."
rows["118:1349208630"]="난 그 텐드에서 느꼈어! 나는 우리가 분명히 승리자 여기 있다고 생각합니다, 소년, 그리고 아레나에 쓰레기"
rows["118:1349732117"]="황금골의 주민 여러분, 흔치 않은 좋은 물건을 믿을 수 없을 만큼 싼값에 팝니다. 이번 기회를 놓치면 후회하실 겁니다!"
rows["118:1352260469"]="내가 이 벌레에 잔인하다고 생각하니?$B$B이번 달 내 두 명을 죽였어"
rows["118:1368642588"]="우리 공예능력을 배우는데 실력도 보여줬어요."
rows["118:1370798868"]="바람이 얼마나 추운지, 옛날에는 이 오래된 뼈들이 절망으로 가득했을 뿐이지만 오늘 저는 희망으로 가득합니다."
rows["118:1372830519"]="그래서 틴브레이드 장군은 죽었어? 그는 남부 바렌스를 통과하는 얼라이언스의 핵심 인물이었어. 인상적 인 작업"
rows["118:1373527808"]="안녕하세요, 영웅님, 두 대륙과 그 밖의 모든 곳에서 최신 소식을 전해드립니다."
rows["118:1385525201"]="네가 오는 줄 알았어, 너나 아리카라와의 연결에 대해 무슨 말인지 신경쓰지 않아"
rows["118:1413852996"]="아아, 행복은 포식한 배라고 생각합니다.$B$B좋은 음식으로 위를 채우고, 따뜻한 마음으로 영혼을 채우세요."
rows["118:1427741085"]="그 조각을 좀 봐봐요, 대령님?"
rows["118:1435937111"]="만약 얼라이언스가 몇 번의 보강이 나의 요새를 정복하는데 필요한 것 같다면, 그들은 또 다른 일을 할 것입니다!"
rows["118:143794772"]="마이클 베더니크와 얘기해봐요.$B$B지도에 그의 위치를 표시해 줄게요"
rows["118:1439458414"]="오라클들 중 가장 존경받는 분들은 그들의 땅을 위해 훌륭하게 일어섰습니다."
rows["118:1459302725"]="희망의 시험을 거쳤고, 적색 크레인의 길을 배웠고,"
rows["118:1460490776"]="동물에 대해 잘 알고 있다고 생각했는데, 이 작은 놈들이 나타나기 전까진"
rows["118:1462239320"]="지금 올께요, 고수님, 다른 것이 필요할까요?"
rows["118:1465066146"]="보수 하오 프램 루가 그의 등산선 끝을 당신에게 넘겨주고 다음 로프 아커에 묶어 산 위로 올라갈 수 있도록 도와줘"
rows["118:1467110880"]="보스가 이렇게 화가 난 적이 없다고 생각합니다.$b$b왕자를 찾아서 조금이라도 차분할 때까지는 안 가"
rows["118:1472309979"]="스톰파이크 구호소는  ⁇  발더에 있습니다  ⁇  발더 바라크 바로 바깥에 있습니다$B$B현재 어느 쪽도 통제하지 않습니다."
rows["118:1483693663"]="착각적인 바르민트는 무해한 무대로 모여서 여러 적들을 공격해서 빨리 죽인다."
rows["118:1512808617"]="지금껏 본 가장 놀라운 엘리베이터를 상상해 보세요. 예, 달콤한 건 아니죠?"
rows["118:1545146635"]="내 허리도 너무 오래 그 상자 안에 갇혀서 약간 딱딱해"
rows["118:1548975369"]="태양샘에 온 것을 환영한다. 날씨도 따뜻하고 경치도 훌륭하지만, 제군들은 이곳에 휴가를 온 것이 아니다!"
rows["118:1555285698"]="여행이 될 거야 하지만 우리가 괴롭힘을 피할 수 있다면, 우리는 낮 끝까지 할 수 있을거야"
rows["118:156001986"]="우리 배 노스렌드 어떻게 배에 들어왔는지 모르겠지만, 모든 사람을 죽였어"
rows["118:1560226635"]="발사당 몇 개의 로켓을 발사할 수 있는 부츠조카를 설정했는데"
rows["118:1563908963"]="잉그바르! 한심한 놈 같으니, 다른 녀석들에게 본보기로 삼아야겠군! 네놈에게 벌을 주겠다... 일어나라! 주인님의 뜻에 따라 저들을 처단하라!"
rows["118:1565577201"]="타나리스의 잃어버린 리거 큐브와 아즈하라의 폭풍의 만 모두 당신의 기술을 향상시키기 위해 선택할 수 있는 상자를 가지고 있습니다."
rows["118:1568276504"]="좋은 형태는 적을 물리치는데 핵심이니까 무기를  ⁇ 지 말고 공격에 규율을 유지하라"
rows["118:1574107939"]="내가 캡틴에게 나에 게 나눌 수 있는 문제에 대해 조언하지만, 그는 당신에게서 듣고 싶어 하는 느낌입니다."
rows["118:1579153149"]="|TInterface\\Icons\\inv_elemental_primal_fire.blp:20|t 알리스라저의 화려한 핵 |cFFFF0000|Hspell:99922|h[Re-Ignites]|h|r!"
rows["118:1598224680"]="만아리... 하지만, 어떻게... 우린 에레다르가 아니에요! 그녀에게 알려야 해요! 그녀 같은 이가 있으면 반드시 찾아서 우리가 누군지 설명해 줘야만 해요..."
rows["118:1598624702"]="그 조각을 좀 봐봐요, 캡틴?"
rows["118:1602767838"]="저는 주요 도시들 사이에 지하로 석유를 운반하는 방법을 연구하고 있지만, 모두가 이것이 꿈이라고 말합니다."
rows["118:1609731097"]="그게... 모두 꿈이었다니? 하늘안개 섬, 핏빛안개 섬, 장가르 습지대, 어둠달 골짜기... 그리고 줄아만까지도... 제인! 어디 있니?!"
rows["118:1630943688"]="우링 피오드 밖에서 아무것도 할 수 없어요. 박쥐는 아직 해외로 가는 길을 몰라요."
rows["118:163631238"]="포털은 닫혀있어요 오크들은 아직  ⁇ 한 땅으로 가는 게이트를 열어두고 있어요"
rows["118:1650629280"]="|TInterface\\Icons\\spell_shadow_destructivesoul.blp:20|t%s 캐스트 |cFFFF0000|Hspell:140543|h[엠파워 에이스]|h|r! 도망치!"
rows["118:1668822899"]="당신께서는 질투로 그를 심판하고 비밀스러운 감옥으로 보내셨습니다. 당신 형제처럼 기꺼이 그를 보냈습니다."
rows["118:1673711876"]="델먼 가족 보석사, 북부 무역 구역과 캐널 사이에, 당신이 찾고 있는 모든 것을 가지고 있어야 합니다."
rows["118:1681445644"]="얼음 폭포가 동쪽으로 있어, 모네. 최고의 갑옷을 가져오세요. 그 얼라이언스는 그들이 무슨 일이 있었는지 알 수 없을 것입니다."
rows["118:1691089263"]="호드 장군은 패배했습니다!$B$B얼라이언스은 승자가 되고, 호드는 이제 약화된 세력을 다시 건설하기 위해 싸우고 있다."
rows["118:1697228367"]="열심히 공부하다 보면 언젠가 직접 소환할 수 있을 걸세. 하지만 지금은 우선 지옥사냥개로 넘어가 보지."
rows["118:1730486045"]="우리가 육지 공격을 하고 싶다면 더 많은 걸 필요로 할 거야"
rows["118:1754997877"]="코렌에게 한 잔을 들어주면\010그리고 허리 블랙브레이스도!\010이 음료는 약하고 발자국도 많지 않습니다.\010하지만 적어도  ⁇ 은  ⁇ 이야!"
rows["118:1769574310"]="워크래프트의 카타클림 콘텐츠를 테스트하는데 시간을 내어 주셔서 감사합니다. \010어디로 가고 싶니?"
rows["118:1772758450"]="이 유물에 대해 제가 모르는 것은 많아요."
rows["118:1779315688"]="호너스와글, 조사팀의 나머지 부에게 알려 주요."
rows["118:1779999097"]="다른 사람들을 화산으로 데려갔어요. 좀비로 변하고,"
rows["118:1788190370"]="이 지역은 불량으로 가득한 것으로 알려져 있습니다 스컬지여러분들이 준비할 수 있는 방어수단을 준비하는 데 시간을 좀 더 투자해 주세요."
rows["118:1799468853"]="이전처럼, 시간이 끝나기 전에 환상의 모든 물결을 물리치세요. 이번에는 더 어려운 환상을 만날 것입니다."
rows["118:1804454884"]="이 갈등은 폭력으로 제대로 해결됐어요!"
rows["118:1810912661"]="네가 상대해야 할 무한의 용군단이 얼마나 되는지 기억이 나면 좋을 텐데. 나한테는 하도 오래전 일이라..."
rows["118:1822669571"]="난 널 가르칠 수 없을거야. 미스터리 능력에 적응하기 위해서는 몇 년의 준비가 필요해"
rows["118:1839884961"]="- 누구야?$B$B<보성자 손들을 들어 올려다.>$B$B내가 다시 연습실로 돌아가서 넌 무시해도 어때?"
rows["118:1841401342"]="자네 같은 사람은 이미 충분히 모집했다고 생각했는데, 지금 보니 아직 자리가 좀 남았군. 시민 연락원에게 보고하게."
rows["118:1843282725"]="블러드힐트가 레온의 착륙을 차지하기 위해 몇 번의 보강이 충분하다고 생각한다면, 그는 또 다른 일을 할 것입니다!"
rows["118:1875485813"]="지옥의 승리가 보장된다고 생각했는데 호드 그래서 저는 제 충성을 바꾸었습니다."
rows["118:1883105577"]="%s는 부패한 달걀을 깨고 - 주변 사람들의 공포와 공포에 - 그 부패한 핵으로부터 술을 마시기 시작합니다."
rows["118:1885496174"]="하지만 아르타스는 이기지 못했고, 매일 그 힘이 줄어들었고, 저주를 받은 자유로워지는 의지를 지배했습니다."
rows["118:1890364595"]="그건 당신 때문이지 내 짓이 아니었어"
rows["118:1907041589"]="아, 네가 그 영웅이로군. 네 꼬마 친구가 너희가 올 거라고 하더구나. 몸소 잡으러 나서는 수고를 덜어주었구나."
rows["118:1908350595"]="왜 이 기억에 붙어있을까?"
rows["118:191928886"]="자네와 거래를 하고 싶지만, 이 모든 물건은 얼라이언스 탐험대의 소유물이다."
rows["118:1928739061"]="유명한 닥터 그레고리 빅토르만이 지금 당신의 능력을 향상시킬 수 있습니다."
rows["118:1938254910"]="이겼든 잃었든, 중위원장이 그런 반려동물을 키우기엔 미친 거 같아\010"
rows["118:1968028044"]="엘리베이터가 시간 내에 작동할지 몰랐기 때문에 나와 동생을 불러들었어요"
rows["118:1992825096"]="내가 여기 두 번이나 왔는데, 두번 모두 네가 불 옆에 앉아 있어"
rows["118:1996629986"]="어쩌면 그럴 수도 있지만 울두어로 다시 침입할 때까지는 시간이 문제야"
rows["118:199736686"]="타란 주와 샤도파인은 내다 내다 내 손에 죽여라 내 반대하는 모든 사람들이 앞으로 죽을 것이다"
rows["118:2015219978"]="우리는 이 질문에 대한 답을 빨리 얻을 수 있기를 바랍니다. 사람들은 두려워하고, 그리고 종파들은 그 두려움을 이용하고 있습니다."
rows["118:2084159845"]="저 비행기 망할 놈이 사고를 살아남지 못했고, 부품을 빼면 다시 작동하지 않을 거야!"
rows["118:2086756058"]="조금이나마 도움을 구해왔어요. 당신이 할 수 있는 능력이 있어서,"
rows["118:2097441969"]="제이드 스쿼시는 우유가 달린 제이드 색을 키우고 내일은 이 야채를 키우기 위해 완벽한 조건이 될 것 같아요"
rows["118:2102756485"]="똑똑한 샤도파네, 내가 널 과소평가했지. 하지만 네 리더는 이제 내다."
